"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Award, BookOpen, Briefcase, FileText, FolderGit2, Hash, Home, Mail, Moon, Sparkles, User } from "lucide-react";
import { cn } from "@/lib/utils";
import { defaultPortfolioData } from "./defaults";
import { DASH, Gap, INK, InkContext, PageThemeContext, SocialIcon, THEME_CSS } from "./parts";
import { Header, type NavLink } from "./sections/Header";
import { Sidebar } from "./sections/Sidebar";
import { Hero } from "./sections/Hero";
import { Terminal } from "./sections/Terminal";
import { About } from "./sections/About";
import { Stack } from "./sections/Stack";
import { Experience } from "./sections/Experience";
import { Projects } from "./sections/Projects";
import { GithubActivity } from "./sections/GithubActivity";
import { Education, Recognition, Writing } from "./sections/Lists";
import { Footer } from "./sections/Footer";
import { BookingDialog, Contact } from "./sections/Contact";
import { SearchDialog, type SearchItem } from "./sections/SearchDialog";
import type { PortfolioData, PortfolioProfile } from "./types";

// A developer portfolio template that fuses three portfolios' taste:
// - Layout: section titles in a left column, content in the middle, a sticky right sidebar with
//   search, theme, what's being built and a live index, all on dashed rails.
// - Detail: corner-bracket titles, a plain text nav with an Open-source pill, bullet intro with
//   bold keywords, featured profile cards, a skills marquee, a dotted experience timeline with
//   Active/Done pills, wide project cards.
// - Finish: hatched breaks, Geist + Geist Mono, icon-boxed info rows, "// 1h ahead" local time,
//   superscript counts, a flat contribution graph, light and dark themes.
// All content comes from `data`; the flat props are shortcuts that win over it. Empty lists hide
// their section.

export interface DeveloperPortfolioProps {
  /** All the content. Anything left out falls back to the placeholder developer. */
  data?: Partial<Omit<PortfolioData, "profile">> & { profile?: Partial<PortfolioProfile> };
  name?: string;
  role?: string;
  company?: string;
  location?: string;
  tagline?: string;
  available?: boolean;
  githubUsername?: string;
  /** Starting theme; visitors can flip it. Default "dark". */
  defaultTheme?: "dark" | "light";
  showStack?: boolean;
  showGithub?: boolean;
  showRecognition?: boolean;
  showEducation?: boolean;
  showWriting?: boolean;
  /** Companies shown before "Show more". Default 3. */
  experienceCount?: number;
  className?: string;
}

const pick = <T,>(value: T | undefined, fallback: T) => (value === undefined ? fallback : value);

function scrollToSection(id: string) {
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  document.getElementById(id)?.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
}

/** The section nearest the top of the viewport. */
function useActiveSection(ids: string[]) {
  const [active, setActive] = useState(ids[0] ?? "");
  const key = ids.join(",");
  useEffect(() => {
    const onScroll = () => {
      let current = ids[0] ?? "";
      for (const id of ids) {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top <= 120) current = id;
      }
      setActive(current);
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true, capture: true });
    return () => window.removeEventListener("scroll", onScroll, { capture: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  return active;
}

export function DeveloperPortfolio({
  data,
  name,
  role,
  company,
  location,
  tagline,
  available,
  githubUsername,
  defaultTheme = "dark",
  showStack = true,
  showGithub = true,
  showRecognition = true,
  showEducation = true,
  showWriting = true,
  experienceCount = 3,
  className,
}: DeveloperPortfolioProps) {
  const content = useMemo<PortfolioData>(() => {
    const base = { ...defaultPortfolioData, ...data } as PortfolioData;
    const profile: PortfolioProfile = { ...defaultPortfolioData.profile, ...data?.profile };
    return {
      ...base,
      profile: {
        ...profile,
        name: pick(name, profile.name),
        role: pick(role, profile.role),
        company: pick(company, profile.company),
        location: pick(location, profile.location),
        tagline: pick(tagline, profile.tagline),
        available: pick(available, profile.available),
      },
      githubUsername: pick(githubUsername, base.githubUsername),
    };
  }, [data, name, role, company, location, tagline, available, githubUsername]);

  const [theme, setTheme] = useState(defaultTheme);
  useEffect(() => setTheme(defaultTheme), [defaultTheme]);
  const toggleTheme = useCallback(() => setTheme((t) => (t === "dark" ? "light" : "dark")), []);

  const { profile } = content;
  const show = {
    about: content.about.length > 0,
    stack: showStack && content.stack.some((g) => g.items.length > 0),
    experience: content.experience.length > 0,
    projects: content.projects.length > 0,
    github: showGithub && Boolean(content.githubUsername),
    recognition: showRecognition && content.recognition.length > 0,
    education: showEducation && content.education.length > 0,
    writing: showWriting && content.posts.length > 0,
  };

  const nav: NavLink[] = [
    { id: "home", label: "Home" },
    show.about && { id: "about", label: "About" },
    show.experience && { id: "experience", label: "Experience" },
    show.projects && { id: "projects", label: "Projects" },
    show.recognition && { id: "achievements", label: "Achievements" },
    show.github && { id: "github", label: "GitHub" },
    show.writing && { id: "writing", label: "Blog" },
    { id: "contact", label: "Contact" },
  ].filter(Boolean) as NavLink[];
  const activeId = useActiveSection(nav.map((link) => link.id));

  // ⌘K / Ctrl+K opens search. Bound in the capture phase and marked handled, so a host page that
  // also uses ⌘K (like a docs shell) leaves it to the portfolio.
  const [searchOpen, setSearchOpen] = useState(false);
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setSearchOpen((open) => !open);
      }
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, []);
  const closeSearch = useCallback(() => setSearchOpen(false), []);
  const [bookingOpen, setBookingOpen] = useState(false);
  const openBooking = useCallback(() => setBookingOpen(true), []);
  const closeBooking = useCallback(() => setBookingOpen(false), []);
  const openSearch = useCallback(() => setSearchOpen(true), []);

  const searchItems = useMemo<SearchItem[]>(() => {
    const go = (id: string) => () => window.setTimeout(() => scrollToSection(id), 50);
    const icons: Record<string, React.ReactNode> = {
      home: <Home />,
      about: <User />,
      experience: <Briefcase />,
      projects: <FolderGit2 />,
      achievements: <Award />,
      github: <SocialIcon platform="github" />,
      writing: <BookOpen />,
      contact: <Mail />,
    };
    return [
      ...nav.map((link) => ({ id: `s-${link.id}`, label: link.label, group: "Sections", icon: icons[link.id] ?? <Hash />, onSelect: go(link.id) })),
      ...content.projects.map((p) => ({
        id: `p-${p.name}`,
        label: p.name,
        group: "Projects",
        icon: <Sparkles />,
        keywords: p.tags,
        url: p.liveUrl ?? p.sourceUrl,
        onSelect: p.liveUrl || p.sourceUrl ? undefined : go("projects"),
      })),
      ...(show.writing ? content.posts.map((post) => ({ id: `b-${post.url}-${post.title}`, label: post.title, group: "Blog", icon: <BookOpen />, url: post.url })) : []),
      ...content.resumes.map((r) => ({ id: `r-${r.label}`, label: `Resume · ${r.label}`, group: "Resume", icon: <FileText />, url: r.url })),
      ...content.socials.map((s) => ({ id: `l-${s.url}`, label: s.label, group: "Links", icon: <SocialIcon platform={s.platform} />, url: s.url })),
      { id: "theme", label: "Toggle theme", group: "Settings", icon: <Moon />, onSelect: toggleTheme },
    ];
    // nav is derived from content and the toggles.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [content, show.writing, show.recognition, show.github, toggleTheme]);

  const sections: React.ReactNode[] = [
    show.about && <About key="about" paragraphs={content.about} highlight={content.aboutHighlight} />,
    show.stack && <Stack key="stack" groups={content.stack} />,
    show.experience && <Experience key="experience" items={content.experience} initialCount={experienceCount} />,
    show.projects && <Projects key="projects" items={content.projects} allUrl={content.projectsUrl} note={content.projectsNote} />,
    show.recognition && <Recognition key="recognition" items={content.recognition} />,
    show.github && <GithubActivity key="github" username={content.githubUsername} />,
    show.education && <Education key="education" items={content.education} />,
    show.writing && <Writing key="writing" posts={content.posts} allUrl={content.blogUrl} />,
  ].filter(Boolean);

  return (
    <div data-theme={theme} className={cn("pf-root min-h-dvh w-full bg-[var(--pf-bg)] text-[var(--pf-fg)]", className)}>
      <style>{THEME_CSS}</style>
      <PageThemeContext.Provider value={theme}>
      <InkContext.Provider value={INK[theme]}>
      <Header nav={nav} activeId={activeId} openSourceUrl={content.openSourceUrl} theme={theme} onToggleTheme={toggleTheme} onOpenSearch={openSearch} />
      <div className={cn("mx-auto grid max-w-[1200px] lg:grid-cols-[minmax(0,1fr)_240px] xl:border-x", DASH)}>
        <main className="min-w-0">
          <Hero
            terminal={<Terminal data={content} theme={theme} onToggleTheme={toggleTheme} onBook={profile.calLink ? openBooking : undefined} />}
            onBook={profile.calLink ? openBooking : undefined}
            profile={profile} intro={content.intro} featured={content.featured} socials={content.socials} resumes={content.resumes} />
          {sections.map((section, i) => (
            <div key={i}>
              <Gap />
              {section}
            </div>
          ))}
          <Contact profile={profile} onBook={profile.calLink ? openBooking : undefined} />
          <Footer profile={profile} socials={content.socials} nav={nav} />
        </main>
        <Sidebar index={nav} activeId={activeId} building={profile.building} theme={theme} onToggleTheme={toggleTheme} onOpenSearch={openSearch} />
      </div>
      <SearchDialog open={searchOpen} onClose={closeSearch} items={searchItems} />
      {profile.calLink && (
        <BookingDialog open={bookingOpen} onClose={closeBooking} calLink={profile.calLink} theme={theme} name={profile.name} />
      )}
      </InkContext.Provider>
      </PageThemeContext.Provider>
    </div>
  );
}

export default DeveloperPortfolio;

// Everything the developer portfolio shows comes from one `PortfolioData` object, so a user swaps
// the data, not the markup. Every list can be empty; its section then hides itself.

export type SocialPlatform = "github" | "x" | "linkedin" | "instagram" | "email" | "website" | "youtube" | "leetcode";

export interface SocialLink {
  platform: SocialPlatform;
  label: string;
  url: string;
}

export interface PortfolioProfile {
  name: string;
  /** e.g. "Design Engineer" */
  role: string;
  /** Where they work now; empty for freelancers. */
  company?: string;
  companyUrl?: string;
  location: string;
  /** IANA zone for the live local clock, e.g. "Asia/Kolkata". */
  timezone: string;
  /** Image URL. Without one the hero shows initials. */
  avatar?: string;
  /** Wide banner image above the profile. Without one a dotted panel shows. */
  cover?: string;
  /** Looping, muted banner video. `cover` shows until it can play, then it fades in. */
  coverVideo?: string;
  /** CSS object-position for the banner crop, e.g. "center 60%". Default "center". */
  coverPosition?: string;
  /** Handle shown in mono under the name, e.g. "@alexrivera". */
  handle?: string;
  /** Shows a verified badge next to the name. */
  verified?: boolean;
  /** One line under the name, e.g. "Engineer | AI | Freelancer". */
  tagline: string;
  /** Words inside the tagline to underline by hand, e.g. "crazy looking softwares". */
  taglineEmphasis?: string;
  /** What they're building now, shown under the handle and in the sidebar. */
  building?: { label: string; url?: string };
  /** Short note next to the booking button, e.g. "30 minutes, no strings." */
  bookingNote?: string;
  /** Shows the "Available for work" status. */
  available: boolean;
  email: string;
  /** Booking link (Cal.com, Calendly…). Hides the button when empty. */
  bookingUrl?: string;
  /** Cal.com "user/event" slug. Embeds the booking calendar in the contact section. */
  calLink?: string;
}

export interface ResumeLink {
  label: string;
  url: string;
}

export interface StackGroup {
  label: string;
  items: string[];
}

export interface ExperienceRole {
  title: string;
  /** "Full-time", "Part-time", "Contract", "Internship"… */
  type: string;
  /** "YYYY-MM" */
  start: string;
  /** "YYYY-MM", or omitted while current. */
  end?: string;
  bullets: string[];
  tags: string[];
}

export type ExperienceIcon = "terminal" | "rocket" | "briefcase" | "code";

export interface Experience {
  company: string;
  url?: string;
  /** Logo image URL. */
  logo?: string;
  /** Icon for the tile when there's no logo; falls back to the first letter. */
  icon?: ExperienceIcon;
  location: string;
  /** "Remote", "On-site", "Hybrid" */
  mode: string;
  roles: ExperienceRole[];
}

export interface Project {
  name: string;
  description: string;
  /** Screenshot URL (16:9 works best). Without one a lined placeholder shows. */
  image?: string;
  /** "YYYY-MM". Leave out to hide the dates. */
  start?: string;
  end?: string;
  tags: string[];
  liveUrl?: string;
  sourceUrl?: string;
}

export type RecognitionKind = "Award" | "Hackathon" | "Certificate" | "Open source";

export interface Recognition {
  title: string;
  kind: RecognitionKind;
  issuer: string;
  /** "YYYY-MM". Leave out to hide it. */
  date?: string;
  url?: string;
}

export interface Education {
  school: string;
  degree: string;
  field: string;
  start: string;
  end?: string;
}

export interface Post {
  title: string;
  /** "YYYY-MM-DD" */
  date: string;
  readMinutes: number;
  /** One or two sentences under the title. */
  summary?: string;
  url: string;
}

/** A highlighted profile card in the hero, e.g. an X account or a community. */
export interface FeaturedCard {
  platform: SocialPlatform | "community";
  title: string;
  subtitle: string;
  /** Button label, e.g. "Follow" or "Join". */
  action: string;
  url: string;
  /** Marks the subtitle with a live dot. */
  live?: boolean;
  /** Shows a verified badge next to the title. */
  verified?: boolean;
}

export interface PortfolioData {
  profile: PortfolioProfile;
  /** Hero bullet points. Wrap words in **double asterisks** to bold them. */
  intro: string[];
  featured: FeaturedCard[];
  socials: SocialLink[];
  resumes: ResumeLink[];
  /** Paragraphs under the greeting. */
  about: string[];
  /** One short clause inside `about` to highlight by hand (≤ ~15 words). */
  aboutHighlight?: string;
  /** GitHub repo or profile for the "Open-source" pill in the header. */
  openSourceUrl?: string;
  stack: StackGroup[];
  experience: Experience[];
  projects: Project[];
  /** Link for "All projects"; hides it when empty. */
  projectsUrl?: string;
  /** Short handwritten sticky note beside the projects (≤ 12 words); hidden when empty. */
  projectsNote?: string;
  /** GitHub username for the contribution graph. */
  githubUsername: string;
  recognition: Recognition[];
  education: Education[];
  posts: Post[];
  /** Link for "All posts"; hides it when empty. */
  blogUrl?: string;
}

"use client";

import { createContext, useContext, type ReactNode } from "react";
import { Globe, Instagram, Mail, Youtube, Code2 } from "lucide-react";
import { cn } from "@/lib/utils";
import type { SocialPlatform } from "./types";

// The portfolio's own look, a fusion of three developer portfolios:
// - a three-column page with dashed rails: section titles on the left, content in the middle,
//   a sticky index on the right; Cabinet Grotesk display headings;
// - corner-bracket section titles, dashed boxes, a dotted timeline and status pills;
// - hatched strips between sections, Geist + Geist Mono, icon-boxed info rows, superscript counts.
// Light and dark themes are CSS variables on the root, so everything reads `var(--pf-*)`.

export const THEME_CSS = `
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400..700&family=Geist+Mono:wght@400..600&family=Reenie+Beanie&display=swap');
@import url('https://api.fontshare.com/v2/css?f[]=cabinet-grotesk@500,700,800&display=swap');
.pf-root{font-family:'Geist',ui-sans-serif,system-ui,sans-serif;-webkit-font-smoothing:antialiased;color-scheme:dark;
  --pf-bg:#0a0a0a;--pf-fg:#fafafa;--pf-muted:#a1a1aa;--pf-subtle:#71717a;--pf-line:rgba(255,255,255,0.1);--pf-dash:rgba(255,255,255,0.16);
  --pf-panel:#131315;--pf-hatch:rgba(255,255,255,0.07);--pf-dot:rgba(255,255,255,0.12);
  --pf-l0:#18181b;--pf-l1:#3f3f46;--pf-l2:#71717a;--pf-l3:#a1a1aa;--pf-l4:#f4f4f5;}
.pf-root[data-theme="light"]{color-scheme:light;
  --pf-bg:#ffffff;--pf-fg:#09090b;--pf-muted:#52525b;--pf-subtle:#a1a1aa;--pf-line:#e4e4e7;--pf-dash:#d4d4d8;
  --pf-panel:#f7f7f8;--pf-hatch:rgba(0,0,0,0.07);--pf-dot:rgba(0,0,0,0.12);
  --pf-l0:#f0f0f2;--pf-l1:#d4d4d8;--pf-l2:#a1a1aa;--pf-l3:#52525b;--pf-l4:#18181b;}
.pf-mono{font-family:'Geist Mono',ui-monospace,SFMono-Regular,Menlo,monospace}
.pf-display{font-family:'Cabinet Grotesk','Geist',ui-sans-serif,system-ui,sans-serif}
.pf-root ::selection{background:var(--pf-fg);color:var(--pf-bg)}
@keyframes pf-marquee{to{transform:translateX(-50%)}}
.pf-marquee{animation:pf-marquee var(--pf-marquee-duration,40s) linear infinite}
.pf-marquee-wrap:hover .pf-marquee{animation-play-state:paused}
@media (prefers-reduced-motion:reduce){.pf-marquee{animation:none}}
`;

/**
 * Ink for the hand-drawn annotations: one pen per page, amber on dark and ballpoint blue on light.
 * A real colour, not a CSS variable, because the marks write it into SVG attributes.
 */
export const INK = { dark: "#FCD34D", light: "#2563EB" } as const;
export const InkContext = createContext<string>(INK.dark);
export const useInk = () => useContext(InkContext);
/** The page theme, for marks whose colour pairs depend on it (the highlighter). */
export const PageThemeContext = createContext<"dark" | "light">("dark");
/** Highlighter behind text: deep indigo under light text on dark, classic yellow under dark text on light. */
export const MARKER = { dark: { color: "#4338CA", opacity: 0.85 }, light: { color: "#FDE68A", opacity: 0.8 } } as const;
export const useMarker = () => MARKER[useContext(PageThemeContext)];
/** Handwriting font for every annotation (arrow labels, sticky note, signature). */
export const HAND = "reenie-beanie" as const;

export const FG = "text-[var(--pf-fg)]";
export const MUTED = "text-[var(--pf-muted)]";
export const SUBTLE = "text-[var(--pf-subtle)]";
export const LINE = "border-[var(--pf-line)]";
export const DASH = "border-dashed border-[var(--pf-dash)]";
export const FOCUS =
  "outline-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--pf-fg)]";
export const HATCH = "bg-[repeating-linear-gradient(-45deg,var(--pf-hatch)_0_1px,transparent_1px_7px)]";
export const DOTS = "bg-[radial-gradient(var(--pf-dot)_1px,transparent_1px)] bg-[length:14px_14px]";

/** Hatched strip between sections. */
export function Gap() {
  return <div aria-hidden="true" className={cn("h-8 border-b", DASH, HATCH)} />;
}

/** A section title framed by four corner brackets. */
export function BracketTitle({ id, children, count }: { id: string; children: ReactNode; count?: number }) {
  const corner = "pointer-events-none absolute size-2 border-[var(--pf-fg)]";
  return (
    <h2 id={id} className={cn("pf-display relative inline-block max-w-full px-2.5 py-1 text-[26px] font-bold leading-tight tracking-[-0.02em]", FG)}>
      <span aria-hidden="true" className={cn(corner, "left-0 top-0 border-l-2 border-t-2")} />
      <span aria-hidden="true" className={cn(corner, "right-0 top-0 border-r-2 border-t-2")} />
      <span aria-hidden="true" className={cn(corner, "bottom-0 left-0 border-b-2 border-l-2")} />
      <span aria-hidden="true" className={cn(corner, "bottom-0 right-0 border-b-2 border-r-2")} />
      {children}
      {count !== undefined && <sup className={cn("pf-mono ml-1 text-xs font-normal tracking-normal", SUBTLE)}>({count})</sup>}
    </h2>
  );
}

/**
 * A page section: on wide screens the bracketed title and an optional note sit in a left column,
 * the content to its right; on phones the title sits on top.
 */
export function Section({
  id,
  title,
  count,
  note,
  aside,
  children,
}: {
  id: string;
  title: string;
  count?: number;
  /** One line under the title. */
  note?: ReactNode;
  /** Extra content under the title, e.g. a "see all" link. */
  aside?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section id={id} aria-labelledby={`${id}-title`} className={cn("grid scroll-mt-16 border-b md:grid-cols-[230px_minmax(0,1fr)]", DASH)}>
      <div className={cn("px-5 pb-2 pt-8 md:border-r md:pb-8", DASH)}>
        <div className="md:sticky md:top-20">
          <BracketTitle id={`${id}-title`} count={count}>
            {title}
          </BracketTitle>
          {note && <p className={cn("mt-3 max-w-[30ch] text-sm leading-relaxed", MUTED)}>{note}</p>}
          {aside && <div className="mt-3">{aside}</div>}
        </div>
      </div>
      <div className="min-w-0 px-5 pb-8 pt-4 md:pt-8">{children}</div>
    </section>
  );
}

export function Tag({ children }: { children: ReactNode }) {
  return (
    <span className={cn("pf-mono inline-flex h-6 items-center rounded-md border px-1.5 text-xs", LINE, MUTED, "bg-[var(--pf-panel)]")}>
      {children}
    </span>
  );
}

export function Tags({ items, className }: { items: string[]; className?: string }) {
  if (!items.length) return null;
  return (
    <ul className={cn("flex flex-wrap gap-1.5", className)} aria-label="Technologies">
      {items.map((item) => (
        <li key={item}>
          <Tag>{item}</Tag>
        </li>
      ))}
    </ul>
  );
}

/** Small bordered square holding an icon. */
export function IconBox({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <span className={cn("grid size-7 shrink-0 place-items-center rounded-md border [&_svg]:size-3.5", LINE, MUTED, "bg-[var(--pf-panel)]", className)}>
      {children}
    </span>
  );
}

/** "Active" / "Done" style pill with a dot. */
export function StatusPill({ tone, children }: { tone: "green" | "red" | "neutral"; children: ReactNode }) {
  const tones = {
    green: "border-emerald-500/30 bg-emerald-500/10 text-emerald-500",
    red: "border-rose-500/30 bg-rose-500/10 text-rose-500",
    neutral: "border-[var(--pf-line)] bg-[var(--pf-panel)] text-[var(--pf-muted)]",
  };
  const dots = { green: "bg-emerald-500", red: "bg-rose-500", neutral: "bg-[var(--pf-subtle)]" };
  return (
    <span className={cn("inline-flex h-5 items-center gap-1 rounded-full border px-1.5 text-[11px] font-medium", tones[tone])}>
      <span aria-hidden="true" className={cn("size-1.5 rounded-full", dots[tone])} />
      {children}
    </span>
  );
}

const BUTTON = {
  base: "inline-flex h-8 items-center justify-center gap-1.5 rounded-md px-3 text-[13px] font-medium transition-colors duration-150 [&_svg]:size-3.5",
  solid: "bg-[var(--pf-fg)] text-[var(--pf-bg)] hover:opacity-90",
  outline: "border border-[var(--pf-line)] text-[var(--pf-fg)] hover:bg-[var(--pf-panel)]",
};

export function LinkButton({
  href,
  variant = "outline",
  children,
  className,
  ...rest
}: { href: string; variant?: "solid" | "outline"; children: ReactNode; className?: string } & Omit<
  React.AnchorHTMLAttributes<HTMLAnchorElement>,
  "href" | "children" | "className"
>) {
  return (
    <a href={href} className={cn(BUTTON.base, BUTTON[variant], FOCUS, className)} {...externalProps(href)} {...rest}>
      {children}
    </a>
  );
}

/** Renders `**bold**` spans inside a sentence. */
export function RichText({ text }: { text: string }) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return (
    <>
      {parts.map((part, i) =>
        part.startsWith("**") && part.endsWith("**") ? (
          <strong key={i} className={cn("font-semibold", FG)}>
            {part.slice(2, -2)}
          </strong>
        ) : (
          <span key={i}>{part}</span>
        )
      )}
    </>
  );
}

// ─── Dates ──────────────────────────────────────────────────────────────────

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function parseMonth(value: string) {
  const [y, m] = value.split("-").map(Number);
  return { y, m: (m || 1) - 1 };
}

/** "01.2026" */
export function formatMonthNum(value: string) {
  const { y, m } = parseMonth(value);
  return `${String(m + 1).padStart(2, "0")}.${y}`;
}

/** "Jan 2026" */
export function formatMonth(value: string) {
  const { y, m } = parseMonth(value);
  return `${MONTHS[m]} ${y}`;
}

/** "Jan 2026 – Now" */
export function formatRange(start: string, end?: string) {
  return `${formatMonth(start)} – ${end ? formatMonth(end) : "Now"}`;
}

/** "01.2026 — ∞" */
export function formatPeriod(start: string, end?: string) {
  return `${formatMonthNum(start)} — ${end ? formatMonthNum(end) : "∞"}`;
}

/** "2y 4m", counting both the first and last month. */
export function formatDuration(start: string, end?: string) {
  const a = parseMonth(start);
  const now = new Date();
  const b = end ? parseMonth(end) : { y: now.getFullYear(), m: now.getMonth() };
  const months = Math.max(1, (b.y - a.y) * 12 + (b.m - a.m) + 1);
  const y = Math.floor(months / 12);
  const m = months % 12;
  return [y && `${y}y`, m && `${m}m`].filter(Boolean).join(" ");
}

/** "Oct 14, 2026" */
export function formatDay(value: string) {
  const [y, m, d] = value.split("-").map(Number);
  return `${MONTHS[(m || 1) - 1]} ${d}, ${y}`;
}

