        <span>heads down, not taking work</span>
      )}
      <span aria-hidden="true">·</span>
      <span>{profile.location.toLowerCase()}</span>
      {local && (
        <>
          <span aria-hidden="true">·</span>
          <span className="tabular-nums">{local.time}</span>
          <span className={SUBTLE}>({local.diff})</span>
        </>
      )}
    </p>
  );
}

type Entry = { id: number; cmd?: string; out?: ReactNode };

export interface TerminalProps {
  data: PortfolioData;
  theme: "dark" | "light";
  onToggleTheme: () => void;
  /** Opens the booking dialog; without it `book` follows bookingUrl. */
  onBook?: () => void;
}

export function Terminal({ data, theme, onToggleTheme, onBook }: TerminalProps) {
  const { profile } = data;
  const user = profile.name.split(" ")[0].toLowerCase();
  const host = (profile.location.split(",").pop() ?? "").trim().toLowerCase().replace(/\s+/g, "-");
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const nextId = useRef(0);
  const [value, setValue] = useState("");
  const [history, setHistory] = useState<string[]>([]);
  const [cursor, setCursor] = useState<number | null>(null);

  // ─── Command table ────────────────────────────────────────────────────────
  const commands = useMemo(() => {
    const projectBySlug = new Map(data.projects.map((p) => [slug(p.name), p]));
    const list = (rows: [ReactNode, ReactNode][]) => (
      <div className="grid grid-cols-[max-content_1fr] gap-x-4">
        {rows.map(([k, v], i) => (
          <div key={i} className="contents">
            <span className={FG}>{k}</span>
            <span>{v}</span>
          </div>
        ))}
      </div>
    );

    const whoami = () => (
      <p>
        {profile.role.toLowerCase()}
        {profile.company && (
          <>
            {" @ "}
            {profile.companyUrl ? <A href={profile.companyUrl}>{profile.company.toLowerCase()}</A> : profile.company.toLowerCase()}
          </>
        )}
      </p>
    );
    const contact = () => (
      <p>
        <A href={`mailto:${profile.email}`}>{profile.email}</A>
      </p>
    );
    const skills = (arg?: string) => {
      const groups = arg ? data.stack.filter((g) => g.label.toLowerCase().startsWith(arg.toLowerCase())) : data.stack;
      if (!groups.length) return <p>skills: no group called &ldquo;{arg}&rdquo;. try: {data.stack.map((g) => g.label.toLowerCase()).join(", ")}</p>;
      return list(groups.map((g) => [g.label.toLowerCase(), g.items.join(", ")]));
    };
    const about = () => (
      <div className="space-y-1.5">
        {data.about.map((p) => (
          <p key={p}>{p}</p>
        ))}
      </div>
    );

    type Cmd = { desc: string; usage?: string; run: (args: string[]) => ReactNode | "clear" };
    const table: Record<string, Cmd> = {
      help: {
        desc: "list commands",
        run: () =>
          list(
            Object.entries(table)
              .filter(([, c]) => c.desc)
              .map(([name, c]) => [c.usage ?? name, c.desc])
          ),
      },
      whoami: { desc: "who is this", run: whoami },
      status: { desc: "availability and local time", run: () => <Status data={data} /> },
      about: { desc: "a little about me", run: about },
      projects: {
        desc: "things I've built",
        run: () =>
          list(
            data.projects.map((p) => [
              slug(p.name),
              <>
                {p.description.split(". ")[0].replace(/\.$/, "")}.{" "}
                {p.liveUrl && <A href={p.liveUrl}>live</A>}
                {p.liveUrl && p.sourceUrl && " · "}
                {p.sourceUrl && <A href={p.sourceUrl}>code</A>}
              </>,
            ])
          ),
      },
      open: {
        desc: "open a project",
        usage: "open <project>",
        run: ([name]) => {
          if (!name) return <p>usage: open &lt;project&gt; · projects: {[...projectBySlug.keys()].join(", ")}</p>;
          const p = projectBySlug.get(slug(name));
          const url = p?.liveUrl ?? p?.sourceUrl;
          if (!p || !url) return <p>open: no project called &ldquo;{name}&rdquo;. try `projects`</p>;
          window.open(url, "_blank", "noopener");
          return <p>opening {p.name}… <A href={url}>{url.replace(/^https?:\/\//, "")}</A></p>;
        },
      },
      skills: { desc: "my stack", usage: "skills [group]", run: ([g]) => skills(g) },
      socials: { desc: "where to find me", run: () => list(data.socials.map((s) => [s.label.toLowerCase(), <A key={s.url} href={s.url}>{s.url.replace(/^mailto:|^https?:\/\/(www\.)?/, "")}</A>])) },
      contact: { desc: "how to reach me", run: contact },
      resume: {
        desc: "download my resume",
        run: () =>
          data.resumes.length ? (
            <div>
              {data.resumes.map((r) => (
                <p key={r.url}>
                  <A href={r.url} download>
                    {r.label.toLowerCase()}.pdf
                  </A>{" "}
                  <span className={SUBTLE}>(click to download)</span>
                </p>
              ))}
            </div>
          ) : (
            <p>no resume yet</p>
          ),
      },
      book: {
        desc: "book a call",
        run: () => {
          if (onBook) {
            onBook();
            return <p>opening the booking calendar…</p>;
          }
          if (profile.bookingUrl) {
            window.open(profile.bookingUrl, "_blank", "noopener");
            return <p>opening <A href={profile.bookingUrl}>{profile.bookingUrl.replace(/^https?:\/\//, "")}</A>…</p>;
          }
          return <p>no booking link. try `contact`</p>;
        },
      },
      theme: {
        desc: "switch light / dark",
        run: () => {
          onToggleTheme();
          return <p>switched to {theme === "dark" ? "light" : "dark"} mode</p>;
        },
      },
      ls: { desc: "list files", run: () => <p className={FG}>about.txt  contact.txt  skills.txt  projects/  resume.pdf</p> },
      cat: {
        desc: "print a file",
        usage: "cat <file>",
        run: ([file]) => {
          switch (file) {
            case "about.txt":
              return about();
            case "contact.txt":
              return contact();
            case "skills.txt":
              return skills();
            case "projects":
            case "projects/":
              return <p>cat: projects: is a directory. try `projects`</p>;
            case "resume.pdf":
              return <p>cat: resume.pdf: binary file. try `resume`</p>;
            case undefined:
              return <p>usage: cat &lt;file&gt; · try `ls`</p>;
            default:
              return <p>cat: {file}: no such file</p>;
          }
        },
      },
      date: { desc: "what time is it", run: () => <p>{new Date().toString()}</p> },
      echo: { desc: "say something", usage: "echo <text>", run: (args) => <p>{args.join(" ")}</p> },
      history: { desc: "past commands", run: () => list(history.map((h, i) => [String(i + 1).padStart(3, " "), h])) },
      clear: { desc: "clear the screen", run: () => "clear" },
      // Undocumented.
      sudo: { desc: "", run: () => <p>{user} is not in the sudoers file. this incident will be reported.</p> },
      exit: { desc: "", run: () => <p>there&rsquo;s no leaving. try `book` instead.</p> },
    };
    return table;
  }, [data, profile, theme, onToggleTheme, onBook, history, user]);

  const boot = (): Entry[] => [
    { id: nextId.current++, cmd: "whoami", out: commands.whoami.run([]) as ReactNode },
    { id: nextId.current++, cmd: "status", out: <Status data={data} /> },
    { id: nextId.current++, cmd: "contact", out: commands.contact.run([]) as ReactNode },
    {
      id: nextId.current++,
      out: (
        <p className={SUBTLE}>
          type <span className={FG}>help</span> to see what else I can do
        </p>
      ),
    },
  ];
  const [entries, setEntries] = useState<Entry[]>(boot);

  // Keep the newest output in view inside the terminal (never scrolls the page).
  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [entries]);

  const run = (raw: string) => {
    const line = raw.trim();
    if (line) setHistory((h) => [...h, line]);
    setCursor(null);
    setValue("");
    if (!line) {
      setEntries((e) => [...e, { id: nextId.current++, cmd: "" }]);
      return;
    }
    const [name, ...args] = line.split(/\s+/);
    const command = commands[name.toLowerCase()];
    const out = command
      ? command.run(args)
      : (
          <p>
            command not found: {name}. type <span className={FG}>help</span>
          </p>
        );
    if (out === "clear") setEntries([]);
    else setEntries((e) => [...e, { id: nextId.current++, cmd: line, out }]);
  };

  const complete = () => {
    const [name, ...rest] = value.trimStart().split(/\s+/);
    if (!rest.length) {
      const matches = Object.keys(commands).filter((c) => commands[c].desc && c.startsWith(name.toLowerCase()));
      if (matches.length === 1) setValue(`${matches[0]} `);
      else if (matches.length > 1) setEntries((e) => [...e, { id: nextId.current++, cmd: value, out: <p className={FG}>{matches.join("  ")}</p> }]);
      return;
    }
    const pool = name === "open" ? data.projects.map((p) => slug(p.name)) : name === "cat" ? ["about.txt", "contact.txt", "skills.txt", "resume.pdf"] : name === "skills" ? data.stack.map((g) => g.label.toLowerCase().split(/\s/)[0]) : [];
    const partial = rest[rest.length - 1] ?? "";
    const matches = pool.filter((p) => p.startsWith(partial.toLowerCase()));
    if (matches.length === 1) setValue(`${name} ${matches[0]}`);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    // Typing here must not trigger the host page's shortcuts (arrow keys, letters).
    event.stopPropagation();
    if (event.key === "Enter") {
      event.preventDefault();
      run(value);
    } else if (event.key === "Tab") {
      event.preventDefault();
      complete();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      if (!history.length) return;
      const i = cursor === null ? history.length - 1 : Math.max(0, cursor - 1);
      setCursor(i);
      setValue(history[i]);
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      if (cursor === null) return;
      const i = cursor + 1;
      if (i >= history.length) {
        setCursor(null);
        setValue("");
      } else {
        setCursor(i);
        setValue(history[i]);
      }
    } else if (event.key.toLowerCase() === "l" && event.ctrlKey) {
      event.preventDefault();
      setEntries([]);
    }
  };

  return (
    <div className={cn("pf-mono mt-6 overflow-hidden rounded-lg border bg-[var(--pf-panel)] text-[13px] leading-6", LINE)}>
      <div className={cn("flex items-center gap-2 border-b px-3 py-2", LINE)}>
        <span aria-hidden="true" className="flex gap-1.5">
          <span className="size-2.5 rounded-full bg-[#FF5F57]" />
          <span className="size-2.5 rounded-full bg-[#FEBC2E]" />
          <span className="size-2.5 rounded-full bg-[#28C840]" />
        </span>
        <span className={cn("mx-auto pr-12 text-xs", SUBTLE)}>
          {user}@{host}: ~
        </span>
      </div>
      {/* Clicking anywhere in the window puts the cursor in the prompt (unless text is being selected). */}
      <div
        ref={scrollRef}
        onClick={() => {
          if (!window.getSelection()?.toString()) inputRef.current?.focus({ preventScroll: true });
        }}
        className={cn("max-h-[300px] cursor-text overflow-y-auto px-4 py-3 [scrollbar-width:thin]", MUTED)}
      >
        <div role="log" aria-live="polite" aria-label="Terminal output" className="space-y-1.5">
          {entries.map((entry) => (
            <div key={entry.id}>
              {entry.cmd !== undefined && (
                <p>
                  <Prompt /> <span className={FG}>{entry.cmd}</span>
                </p>
              )}
              {entry.out}
            </div>
          ))}
        </div>
        <div className="mt-1.5 flex items-center gap-2">
          <Prompt />
          <label htmlFor={inputId} className="sr-only">
            Terminal command
          </label>
          <input
            id={inputId}
            ref={inputRef}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={onKeyDown}
            autoComplete="off"
            autoCapitalize="off"
            autoCorrect="off"
            spellCheck={false}
            placeholder="type help"
            className={cn("min-w-0 flex-1 bg-transparent caret-emerald-500 outline-none placeholder:text-[var(--pf-subtle)]", FG)}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState, type ReactNode } from "react";
import { CornerDownLeft, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { FG, LINE, MUTED, SUBTLE } from "../parts";

export interface SearchItem {
  id: string;
  label: string;
  group: string;
  icon: ReactNode;
  keywords?: string[];
  /** Either a link to open or an action to run. */
  url?: string;
  onSelect?: () => void;
}

/** ⌘K search: a native modal <dialog> with a filter box and a keyboard-driven list. */
export function SearchDialog({ open, onClose, items }: { open: boolean; onClose: () => void; items: SearchItem[] }) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const listId = useId();

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      setQuery("");
      setActive(0);
      dialog.showModal();
      inputRef.current?.focus();
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter((item) => [item.label, item.group, ...(item.keywords ?? [])].some((v) => v.toLowerCase().includes(q)));
  }, [items, query]);

  const run = (item: SearchItem | undefined) => {
    if (!item) return;
    onClose();
    if (item.onSelect) item.onSelect();
    else if (item.url) {
      if (/^https?:\/\//.test(item.url)) window.open(item.url, "_blank", "noopener");
      else window.location.href = item.url;
    }
  };

  useEffect(() => {
    document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: "nearest" });
  }, [active, listId]);

  let lastGroup = "";
  return (
    <dialog
      ref={dialogRef}
      onClose={onClose}
      onClick={(event) => event.target === dialogRef.current && onClose()}
      aria-label="Search"
      className={cn(
        "m-auto mt-[12vh] w-[min(560px,calc(100vw-2rem))] overflow-hidden rounded-xl border bg-[var(--pf-bg)] p-0 shadow-2xl backdrop:bg-black/50 backdrop:backdrop-blur-[2px]",
        LINE
      )}
    >
      <div className={cn("flex items-center gap-2 border-b px-3", LINE)}>
        <Search className={cn("size-4 shrink-0", SUBTLE)} aria-hidden="true" />
        <input
          ref={inputRef}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setActive(0);
          }}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown") {
              event.preventDefault();
              setActive((i) => (results.length ? (i + 1) % results.length : 0));
            } else if (event.key === "ArrowUp") {
              event.preventDefault();
              setActive((i) => (results.length ? (i - 1 + results.length) % results.length : 0));
            } else if (event.key === "Enter") {
              event.preventDefault();
              run(results[active]);
            }
          }}
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={results.length ? `${listId}-${active}` : undefined}
          placeholder="Type to search…"
          className={cn("h-12 flex-1 bg-transparent text-sm outline-none placeholder:text-[var(--pf-subtle)]", FG)}
        />
        <kbd className={cn("pf-mono rounded border bg-[var(--pf-panel)] px-1.5 text-[11px]", LINE, SUBTLE)}>Esc</kbd>
      </div>

      <ul id={listId} role="listbox" className="max-h-[50vh] overflow-y-auto p-1.5">
        {results.map((item, index) => {
          const header = item.group !== lastGroup;
          lastGroup = item.group;
          return (
            <li key={item.id} role="presentation">
              {header && <p className={cn("pf-mono px-2 pb-1 pt-2.5 text-[11px]", SUBTLE)}>{item.group}</p>}
              <div
                id={`${listId}-${index}`}
                role="option"
                aria-selected={index === active}
                onMouseMove={() => setActive(index)}
                onClick={() => run(item)}
                className={cn(
                  "flex cursor-pointer items-center gap-2.5 rounded-md px-2 py-2 text-sm [&_svg]:size-4",
                  index === active ? cn("bg-[var(--pf-panel)]", FG) : MUTED
                )}
              >
                {item.icon}
                <span className="flex-1 truncate">{item.label}</span>
                {index === active && <CornerDownLeft className={SUBTLE} aria-hidden="true" />}
              </div>
            </li>
          );
        })}
        {results.length === 0 && <li className={cn("px-2 py-8 text-center text-sm", MUTED)}>No results for “{query}”.</li>}
      </ul>
    </dialog>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import React from "react";
import { RoughCircle } from "./roughly/RoughCircle";
import { RoughUnderline } from "./roughly/RoughUnderline";
import { RoughStrike, type StrikeVariant } from "./roughly/RoughStrike";
import { RoughCross, type CrossVariant } from "./roughly/RoughCross";
import {
  RoughBracket,
  type BracketSide,
  type BracketStyle,
} from "./roughly/RoughBracket";
import { RoughHighlight } from "./roughly/RoughHighlight";
import { RoughBox, type BoxVariant } from "./roughly/RoughBox";
import {
  RoughArrow,
  type ArrowPlacement,
  type ArrowVariant,
  type ArrowheadStyle,
  type ArrowLabelFont,
  type ArrowLabelPlacement,
} from "./roughly/RoughArrow";
import {
  RoughHandwriting,
  type HandwritingFont,
  type RoughHandwritingProps,
} from "./roughly/RoughHandwriting";
import { RoughCheck, type CheckMark } from "./roughly/RoughCheck";
import { RoughSticky, type StickyPin, type StickyFont } from "./roughly/RoughSticky";

export type RoughlyType =
  | "underline"
  | "circle"
  | "strike-through"
  | "cross-off"
  | "bracket"
  | "box"
  | "highlight"
  | "arrow"
  | "handwriting"
  | "check"
  | "sticky";

export type { BracketSide, BracketStyle } from "./roughly/RoughBracket";
export type { BoxVariant } from "./roughly/RoughBox";
export type {
  ArrowPlacement,
  ArrowVariant,
  ArrowheadStyle,
  ArrowLabelFont,
  ArrowLabelPlacement,
};
export type { HandwritingFont, RoughHandwritingProps };

export type UnderlineVariant = "single" | "double" | "wavy";
export type { StrikeVariant } from "./roughly/RoughStrike";
export type { CrossVariant } from "./roughly/RoughCross";
export type { CheckMark, CheckSide } from "./roughly/RoughCheck";
export type { StickyPlacement, StickyPin, StickyFont } from "./roughly/RoughSticky";

export interface RoughlyProps {
  children?: React.ReactNode;
  /** Type of annotation */
  type?: RoughlyType;
  /** Stroke / highlight color */
  color?: string;
  /** Stroke width for lines, circles, boxes, and brackets (in px) */
  strokeWidth?: number;
  /** Whether to animate the drawing stroke */
  animate?: boolean;
  /** Animation duration in ms */
  animationDuration?: number;
  /** Placement side when type is 'bracket' ('left' | 'right' | 'top' | 'bottom') */
  brackets?: BracketSide;
  /** Alias for brackets prop */
  side?: BracketSide;
  /** Bracket style: 'curly' ({) or 'square' ([) */
  bracketStyle?: BracketStyle;
  /** Variant for underline ('single' | 'double' | 'wavy'), strike-through ('single' | 'double' | 'triple'), cross-off ('single' | 'double'), or box ('single' | 'double') */
  variant?: UnderlineVariant | StrikeVariant | CrossVariant | BoxVariant;
  /** Margin mark when type is 'check': 'check' (✓) | 'cross' (✗) (default: 'check') */
  mark?: CheckMark;
  /** Whether the 'check' mark is drawn; flip to draw / erase (default: true) */
  checked?: boolean;
  /** Handwritten note text when type is 'sticky' */
  note?: React.ReactNode;
  /** Sticky note attachment: 'tape' | 'pin' | 'none' (default: 'tape') */
  pin?: StickyPin;
  /** Sticky note paper color (default: "#FDE68A") */
  paper?: string;
  /** Placement direction when type is 'arrow' */
  placement?: ArrowPlacement;
  /** Overall arrow scale: length, arrowhead and gap grow together (default: 1) */
  arrowSize?: number;
  /** Signed arc bend from -1 to 1; 0 is straight, negative bends the other way (default: 0.38) */
  arrowBend?: number;
  /** Arrow curve variant ('curved' | 'straight' | 's-curve') */
  arrowVariant?: ArrowVariant;
  /** Arrowhead style ('open' | 'filled') */
  arrowhead?: ArrowheadStyle;
  /** Callout label for arrow */
  arrowLabel?: React.ReactNode;
  /** Callout label font family ('caveat' | 'reenie-beanie' | 'kalam') */
  arrowLabelFont?: ArrowLabelFont;
  /** Font size in pixels for arrow callout text */
  arrowLabelFontSize?: number;
  /** Font thickness (weight, e.g. 300 to 650) for arrow callout text */
  arrowLabelFontWeight?: number;
  /** Optional custom horizontal offset in pixels for arrow callout text */
  arrowLabelOffsetX?: number;
  /** Optional custom vertical offset in pixels for arrow callout text */
  arrowLabelOffsetY?: number;
  /** Relative placement of label around arrow tail: 'auto' | 'top' | 'bottom' | 'left' | 'right' (default: "auto") */
  arrowLabelPlacement?: ArrowLabelPlacement;
  /** Gap distance in pixels between arrow tail and callout label (default: 8) */
  arrowLabelDistance?: number;
  /** Rotation angle in degrees for arrow callout text (default: 0) */
  arrowLabelRotate?: number;
  /** Optional custom text color for arrow callout text (defaults to arrow color) */
  arrowLabelColor?: string;
  /** @deprecated Use `arrowBend`. Arc curvature intensity for curved arrows */
  arrowCurvature?: number;
  /** Handwriting font family: 'reenie-beanie' | 'caveat' | 'kalam' (default: "reenie-beanie") */
  font?: HandwritingFont;
  /** Optional custom URL to .ttf font file for handwriting */
  fontUrl?: string;
  /** Enable interactive live-typing handwriting input mode (default: false) */
  editable?: boolean;
  /** Value for handwriting in controlled mode */
  value?: string;
  /** Default value for handwriting in uncontrolled mode */
  defaultValue?: string;
  /** Placeholder for handwriting in editable mode */
  placeholder?: string;
  /** Change callback for handwriting in editable mode */
  onChange?: (text: string) => void;
  /** Font size in px for handwriting glyph rendering (default: 40) */
  fontSize?: number;
  /** Maximum words allowed for handwriting (default: 6) */
  maxWords?: number;
  /** Maximum characters allowed for handwriting (default: 50) */
  maxLength?: number;
  /** Custom wrapper class */
  className?: string;
  /** Custom text class */
  textClassName?: string;
}

// Default colors matching dark-first Void UI palette
const DEFAULT_COLORS: Record<RoughlyType, string> = {
  underline: "#6366F1", // Indigo
  circle: "#EC4899", // Rose / Pink
  "strike-through": "#EF4444", // Crimson Red
  "cross-off": "#EF4444", // Crimson Red
  bracket: "#10B981", // Emerald Green
  box: "#10B981", // Emerald Green
  highlight: "#4338CA", // Deep Royal Indigo
  arrow: "#F59E0B", // Cyber Amber
  handwriting: "#6366F1", // Indigo
  check: "#10B981", // Emerald Green
  sticky: "#3B2A14", // Pencil ink on paper
};

export function Roughly({
  children,
  type = "underline",
  color,
  strokeWidth = 2,
  animate = true,
  animationDuration = 750,
  brackets,
  side,
  bracketStyle = "curly",
  variant = "single",
  placement,
  arrowSize,
  arrowBend,
  arrowVariant,
  arrowhead,
  arrowLabel,
  arrowLabelFont,
  arrowLabelFontSize,
  arrowLabelFontWeight,
  arrowLabelOffsetX,
  arrowLabelOffsetY,
  arrowLabelPlacement,
  arrowLabelDistance,
  arrowLabelRotate,
  arrowLabelColor,
  arrowCurvature,
  font,
  fontUrl,
  editable,
  value,
  defaultValue,
  placeholder,
  onChange,
  fontSize,
  maxWords,
  maxLength,
  mark = "check",
  checked,
  note,
  pin,
  paper,
  className = "",
  textClassName = "",
}: RoughlyProps) {
  if (type === "circle") {
    return (
      <RoughCircle
        color={color || DEFAULT_COLORS.circle}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughCircle>
    );
  }

  if (type === "underline") {
    return (
      <RoughUnderline
        variant={variant as UnderlineVariant}
        color={color || DEFAULT_COLORS.underline}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughUnderline>
    );
  }

  if (type === "strike-through") {
    return (
      <RoughStrike
        variant={(variant as StrikeVariant) || "single"}
        color={color || DEFAULT_COLORS["strike-through"]}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughStrike>
    );
  }

  if (type === "cross-off") {
    return (
      <RoughCross
        variant={(variant as CrossVariant) || "single"}
        color={color || DEFAULT_COLORS["cross-off"]}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughCross>
    );
  }

  if (type === "bracket") {
    return (
      <RoughBracket
        side={side || brackets || "left"}
        bracketStyle={bracketStyle}
        color={color || DEFAULT_COLORS.bracket}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughBracket>
    );
  }

  if (type === "highlight") {
    return (
      <RoughHighlight
        color={color || DEFAULT_COLORS.highlight}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughHighlight>
    );
  }

  if (type === "box") {
    return (
      <RoughBox
        variant={(variant as BoxVariant) || "double"}
        color={color || DEFAULT_COLORS.box}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughBox>
    );
  }

  if (type === "arrow") {
    return (
      <RoughArrow
        placement={placement}
        size={arrowSize}
        bend={arrowBend}
        variant={arrowVariant}
        arrowhead={arrowhead}
        label={arrowLabel}
        labelFont={arrowLabelFont}
        labelFontSize={arrowLabelFontSize}
        labelFontWeight={arrowLabelFontWeight}
        labelPlacement={arrowLabelPlacement}
        labelDistance={arrowLabelDistance}
        labelRotate={arrowLabelRotate}
        labelColor={arrowLabelColor}
        labelOffsetX={arrowLabelOffsetX}
        labelOffsetY={arrowLabelOffsetY}
        curvature={arrowCurvature}
        color={color || DEFAULT_COLORS.arrow}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughArrow>
    );
  }

  if (type === "handwriting") {
    return (
      <RoughHandwriting
        font={font}
        fontUrl={fontUrl}
        color={color || DEFAULT_COLORS.handwriting}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        fontSize={fontSize}
        maxWords={maxWords}
        maxLength={maxLength}
        editable={editable}
        value={value}
        defaultValue={defaultValue}
        placeholder={placeholder}
        onChange={onChange}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughHandwriting>
    );
  }

  if (type === "check") {
    const checkSide = side === "right" ? "right" : "left";
    return (
      <RoughCheck
        mark={mark}
        side={checkSide}
        checked={checked}
        color={color || (mark === "cross" ? "#F43F5E" : DEFAULT_COLORS.check)}
        strokeWidth={strokeWidth}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughCheck>
    );
  }

  if (type === "sticky") {
    return (
      <RoughSticky
        note={note}
        placement={placement}
        pin={pin}
        paper={paper}
        font={(font as StickyFont | undefined) ?? arrowLabelFont}
        fontSize={fontSize}
        color={color || DEFAULT_COLORS.sticky}
        animate={animate}
        animationDuration={animationDuration}
        className={className}
        textClassName={textClassName}
      >
        {children}
      </RoughSticky>
    );
  }

  return (
    <RoughUnderline
      variant="single"
      color={color || DEFAULT_COLORS.underline}
      strokeWidth={strokeWidth}
      animate={animate}
      animationDuration={animationDuration}
      className={className}
      textClassName={textClassName}
    >
      {children}
    </RoughUnderline>
  );
}

