"use client";

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { INSTANT, useRoughMotion } from "./useRoughMotion";
import { motion } from "framer-motion";

export type ArrowPlacement =
  | "top"
  | "top-right"
  | "top-left"
  | "bottom"
  | "bottom-right"
  | "bottom-left"
  | "left"
  | "right";

export type ArrowVariant = "curved" | "straight" | "s-curve";

export type ArrowheadStyle = "open" | "filled";

export type ArrowLabelFont = "caveat" | "reenie-beanie" | "kalam";

export type ArrowLabelPlacement = "auto" | "top" | "bottom" | "left" | "right";

export interface RoughArrowProps {
  /** Target element or text to point to (optional; if omitted, renders standalone) */
  children?: React.ReactNode;
  /** Direction from which the arrow points toward the target (default: "top-right") */
  placement?: ArrowPlacement;
  /** Overall scale of the arrow: length, arrowhead and target gap grow together (default: 1) */
  size?: number;
  /** Signed arc bend, -1 to 1 (0 = straight). Unset = auto: the sign and depth that land the head on the target for this placement (±0.32 corners, ±0.2 sides). Override only the depth, keep the auto sign (default: auto) */
  bend?: number;
  /** Curve shape: 'curved' (single arc) | 'straight' | 's-curve' (default: "curved") */
  variant?: ArrowVariant;
  /** Arrowhead style: 'open' (>) or 'filled' (solid triangle) (default: "open") */
  arrowhead?: ArrowheadStyle;
  /** Stroke color (default: "#F59E0B" Cyber Amber) */
  color?: string;
  /** Stroke thickness in pixels (default: 2) */
  strokeWidth?: number;
  /** Number of pen passes (1 = clean single line, 2 = sketchy double line) (default: 1) */
  iterations?: number;
  /** How much the pen passes drift from the ideal arc. The arc itself never kinks (default: 1) */
  roughness?: number;
  /** Seed for the hand-drawn variation, so several arrows on a page differ (default: derived from placement) */
  seed?: number;
  /** Callout label text placed near the tail of the arrow */
  label?: React.ReactNode;
  /** Callout label font family: 'caveat' | 'reenie-beanie' | 'kalam' (default: "caveat") */
  labelFont?: ArrowLabelFont;
  /** Callout label font size in pixels (default: resolved per font family) */
  labelFontSize?: number;
  /** Callout label font thickness (weight, e.g. 300 to 650) (default: 400) */
  labelFontWeight?: number;
  /** Relative placement of label around arrow tail: 'auto' | 'top' | 'bottom' | 'left' | 'right' (default: "auto") */
  labelPlacement?: ArrowLabelPlacement;
  /** Gap distance in pixels between arrow tail and callout label (default: 8) */
  labelDistance?: number;
  /** Rotation angle in degrees for playful hand-drawn tilt (default: 0) */
  labelRotate?: number;
  /** Optional custom text color for the callout label (defaults to arrow color) */
  labelColor?: string;
  /** Optional custom horizontal offset in pixels for callout label */
  labelOffsetX?: number;
  /** Optional custom vertical offset in pixels for callout label */
  labelOffsetY?: number;
  /** Exact distance in pixels between tail and target; overrides `size` for length (default: 65 × size) */
  distance?: number;
  /** Exact gap in pixels between tip and target edge; overrides `size` for the gap (default: 8 × size) */
  offset?: number;
  /** @deprecated Use `bend`. Arc intensity for curved arrows */
  curvature?: number;
  /** @deprecated Use a negative `bend`. Inverts the arc direction */
  flipCurve?: boolean;
  /** @deprecated No longer used; the arc is always a single smooth curve */
  bowing?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Total drawing animation duration in milliseconds (default: 800) */
  animationDuration?: number;
  /** Delay before drawing animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Additional CSS class names for the wrapping container */
  className?: string;
  /** Additional CSS class names for the inner text / content */
  textClassName?: string;
  /** Additional CSS class names for the callout label */
  labelClassName?: string;
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

interface Point {
  x: number;
  y: number;
}

const labelFontClassMap: Record<ArrowLabelFont, string> = {
  caveat: "font-[family-name:var(--font-caveat,'Caveat'),cursive] text-lg",
  "reenie-beanie": "font-[family-name:'Reenie_Beanie',cursive] text-2xl tracking-wide",
  kalam: "font-[family-name:'Kalam',cursive] text-lg",
};

const BASE_LENGTH = 65;
const BASE_GAP = 8;
const BARB_ANGLE = 28 * (Math.PI / 180);

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

/**
 * The bend that makes the arrowhead land head-on (within ~15°) on the target's edge for each placement.
 * The head arrives rotated atan(3·bend) off the tail→tip line, so the sign must turn it *toward* the
 * target's edge normal: top-right / bottom-left / top / left bow one way, their mirrors the other.
 * An s-curve arrives on the opposite side of its chord, so its sign flips.
 */
const AUTO_BEND: Record<ArrowPlacement, number> = {
  "top-right": 0.32,
  "bottom-left": 0.32,
  "top-left": -0.32,
  "bottom-right": -0.32,
  top: 0.2,
  left: 0.2,
  bottom: -0.2,
  right: -0.2,
};

/** Default `bend` for a placement (and variant): the arc that lands the arrowhead head-on. */
export function arrowAutoBend(placement: ArrowPlacement, variant: ArrowVariant = "curved"): number {
  if (variant === "straight") return 0;
  const b = AUTO_BEND[placement] ?? 0.32;
  return variant === "s-curve" ? -b : b;
}

// Deterministic PRNG so server and client draw the same arrow (no hydration mismatch)
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(str: string) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 16777619);
  }
  return h >>> 0;
}

const fmt = (n: number) => Math.round(n * 100) / 100;

export function RoughArrow({
  children,
  placement = "top-right",
  size = 1,
  bend,
  variant = "curved",
  arrowhead = "open",
  color = "#F59E0B",
  strokeWidth = 2,
  iterations = 1,
  roughness = 1,
  seed,
  label,
  labelFont = "caveat",
  labelFontSize,
  labelFontWeight,
  labelPlacement = "auto",
  labelDistance = 8,
  labelRotate = 0,
  labelColor,
  labelOffsetX = 0,
  labelOffsetY = 0,
  distance,
  offset,
  curvature,
  flipCurve = false,
  animate: animateProp = true,
  animationDuration = 800,
  animationDelay = 0,
  className = "",
  textClassName = "",
  labelClassName = "",
}: RoughArrowProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const [dimensions, setDimensions] = useState<{ width: number; height: number } | null>(null);
  const [inView, setInView] = useState(!animate);

  // Measure container dimensions via ResizeObserver and font loading synchronization
  useIsomorphicLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return undefined;

    const measure = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        setDimensions({ width: rect.width, height: rect.height });
      }
    };

    measure();

    if (typeof document !== "undefined" && "fonts" in document) {
      document.fonts.ready.then(measure).catch(() => {});
    }

    if (typeof ResizeObserver === "undefined") {
      return undefined;
    }

    const ro = new ResizeObserver(() => measure());
    ro.observe(el);
    return () => ro.disconnect();
  }, [children]);

  // Scroll intersection observer
  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }

    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setInView(true);
        });
      });
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          requestAnimationFrame(() => {
            requestAnimationFrame(() => {
              setInView(true);
            });
          });
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  // Resolved geometry coordinates relative to the target container
  const w = dimensions?.width || (children ? 80 : 0);
  const h = dimensions?.height || (children ? 24 : 0);
  const scale = clamp(size, 0.25, 4);
  const D = distance ?? BASE_LENGTH * scale;
  const gap = offset ?? BASE_GAP * scale;

  // One signed bend value: explicit `bend`, else legacy curvature/flipCurve, else the per-placement auto bend
  const autoBend = arrowAutoBend(placement, variant);
  const resolvedBend =
    variant === "straight"
      ? 0
      : clamp(
          bend ??
            (curvature !== undefined
              ? flipCurve ? -curvature : curvature
              : flipCurve ? -autoBend : autoBend),
          -1,
          1
        );
  const resolvedSeed = seed ?? hashString(`${placement}|${variant}`);

  const { tail, tip, labelPos, labelTransform } = useMemo(() => {
    let P_tip: Point;
    let P_tail: Point;
    let lblPos: Point;
    let lblTransform = "";

    // 1. Calculate Tip and Tail Coordinates based on Placement
    switch (placement) {
      case "top-right":
      case "top-left":
      case "top": {
        P_tip = {
          x: placement === "top-right" ? w * 0.85 : placement === "top-left" ? w * 0.15 : w * 0.5,
          y: -gap,
        };
        P_tail = {
          x: placement === "top-right" ? w + D * 0.75 : placement === "top-left" ? -D * 0.75 : w * 0.5 + D * 0.35,
          y: -gap - D,
        };
        break;
      }

      case "bottom-right":
      case "bottom-left":
      case "bottom": {
        P_tip = {
          x: placement === "bottom-right" ? w * 0.85 : placement === "bottom-left" ? w * 0.15 : w * 0.5,
          y: h + gap,
        };
        P_tail = {
          x: placement === "bottom-right" ? w + D * 0.75 : placement === "bottom-left" ? -D * 0.75 : w * 0.5 + D * 0.35,
          y: h + gap + D,
        };
        break;
      }

      case "left": {
        P_tip = { x: -gap, y: h * 0.5 };
        P_tail = { x: -gap - D, y: h * 0.5 - D * 0.3 };
        break;
      }

      case "right": {
        P_tip = { x: w + gap, y: h * 0.5 };
        P_tail = { x: w + gap + D, y: h * 0.5 - D * 0.3 };
        break;
      }

      default: {
        P_tip = { x: w * 0.85, y: -gap };
        P_tail = { x: w + D * 0.75, y: -gap - D };
        break;
      }
    }

    // 2. Resolve Directional Placement around Tail
    const effectivePlacement: "top" | "bottom" | "left" | "right" =
      labelPlacement === "auto"
        ? (placement.startsWith("bottom")
            ? "bottom"
            : placement === "left"
            ? "left"
            : placement === "right"
            ? "right"
            : "top")
        : labelPlacement;

    const flipped = resolvedBend < 0;
    const rotStr = labelRotate ? ` rotate(${labelRotate}deg)` : "";

    switch (effectivePlacement) {
      case "top": {
        const topYOffset = labelPlacement === "auto" ? (flipped ? -15 : -labelDistance) : -labelDistance;
        lblPos = { x: P_tail.x + labelOffsetX, y: P_tail.y + topYOffset + labelOffsetY };
        lblTransform = `translate(-50%, -100%)${rotStr}`;
        break;
      }
      case "bottom": {
        const bottomYOffset = labelPlacement === "auto" ? (flipped ? -2 : labelDistance) : labelDistance;
        lblPos = { x: P_tail.x + labelOffsetX, y: P_tail.y + bottomYOffset + labelOffsetY };
        lblTransform = `translate(-50%, 0)${rotStr}`;
        break;
      }
      case "left": {
        const leftYOffset = labelPlacement === "auto" ? (flipped ? -6 : 0) : 0;
        lblPos = { x: P_tail.x - labelDistance + labelOffsetX, y: P_tail.y + leftYOffset + labelOffsetY };
        lblTransform = `translate(-100%, -50%)${rotStr}`;
        break;
      }
      case "right": {
        const rightYOffset = labelPlacement === "auto" ? (flipped ? -6 : 0) : 0;
        lblPos = { x: P_tail.x + labelDistance + labelOffsetX, y: P_tail.y + rightYOffset + labelOffsetY };
        lblTransform = `translate(0, -50%)${rotStr}`;
        break;
      }
    }

    return { tail: P_tail, tip: P_tip, labelPos: lblPos, labelTransform: lblTransform };
  }, [w, h, D, gap, placement, resolvedBend, labelOffsetX, labelOffsetY, labelPlacement, labelDistance, labelRotate]);

  // Build the shaft as true cubic Béziers (never resampled), so the line is always one smooth arc
  const { shaftPaths, headPaths } = useMemo(() => {
    const rand = mulberry32(resolvedSeed);
    const jitter = () => rand() * 2 - 1;

    const isS = variant === "s-curve";

    // Symmetric control points at 1/3 and 2/3 of the chord, pushed out by the same depth, give an
    // even, near-circular arc with no hook. Such a curve can never inflect, so it never kinks.
    const arc = (from: Point, bendRatio: number) => {
      const dx = tip.x - from.x;
      const dy = tip.y - from.y;
      const chord = Math.hypot(dx, dy) || 1;
      // Perpendicular normal; positive bend bows to this side
      const nx = -dy / chord;
      const ny = dx / chord;
      const depth = bendRatio * chord;
      return {
        chord,
        nx,
        ny,
        c1: { x: from.x + dx / 3 + nx * depth, y: from.y + dy / 3 + ny * depth },
        c2: {
          x: from.x + (dx * 2) / 3 + nx * depth * (isS ? -1 : 1),
          y: from.y + (dy * 2) / 3 + ny * depth * (isS ? -1 : 1),
        },
      };
    };
    const toPath = (from: Point, c1: Point, c2: Point) =>
      `M ${fmt(from.x)} ${fmt(from.y)} C ${fmt(c1.x)} ${fmt(c1.y)}, ${fmt(c2.x)} ${fmt(c2.y)}, ${fmt(tip.x)} ${fmt(tip.y)}`;

    // Pass 0 is the clean arc; a tiny per-arrow depth variation keeps it feeling hand-drawn
    const mainBend = resolvedBend * (1 + jitter() * 0.05 * roughness);
    const main = arc(tail, mainBend);
    const chord = main.chord;

    // Exact arrival direction of the curve at the tip: B'(1) ∝ tip − c2
    let tx = tip.x - main.c2.x;
    let ty = tip.y - main.c2.y;
    const tLen = Math.hypot(tx, ty) || 1;
    tx /= tLen;
    ty /= tLen;

    const passes = clamp(Math.round(iterations), 1, 3);
    const amp = roughness * clamp(chord * 0.025, 0.8, 3);
    const shaft: string[] = [toPath(tail, main.c1, main.c2)];

    // Extra passes start from a slightly shifted tail and are rebuilt as their own symmetric arc to
    // the same tip, always bowing to the main arc's side, so they stay single smooth curves.
    const side = mainBend !== 0 ? Math.sign(mainBend) : jitter() < 0 ? -1 : 1;
    for (let i = 1; i < passes; i++) {
      const from = {
        x: tail.x + main.nx * jitter() * amp - main.ny * jitter() * amp * 0.6,
        y: tail.y + main.ny * jitter() * amp + main.nx * jitter() * amp * 0.6,
      };
      const drift = (Math.abs(mainBend) * (1 + jitter() * 0.08) + (Math.abs(jitter()) * amp * 0.5) / chord) * side;
      const pass = arc(from, isS ? mainBend : drift);
      shaft.push(toPath(from, pass.c1, pass.c2));
    }

    // Arrowhead scales with the arrow, never smaller than the stroke can carry
    const headLen = Math.max(clamp(chord * 0.16, 7, 24), strokeWidth * 3.5);
    const theta = Math.atan2(ty, tx);
    const barb = (sign: 1 | -1) => {
      const len = headLen * (1 + jitter() * 0.06 * roughness);
      const ang = BARB_ANGLE + jitter() * 0.03 * roughness;
      return {
        x: tip.x - len * Math.cos(theta + sign * ang),
        y: tip.y - len * Math.sin(theta + sign * ang),
      };
    };

    const head: string[] = [];
    const headPasses = arrowhead === "filled" ? 1 : passes;
    for (let i = 0; i < headPasses; i++) {
      const b1 = barb(-1);
      const b2 = barb(1);
      head.push(
        arrowhead === "filled"
          ? `M ${fmt(tip.x)} ${fmt(tip.y)} L ${fmt(b1.x)} ${fmt(b1.y)} L ${fmt(b2.x)} ${fmt(b2.y)} Z`
          : `M ${fmt(b1.x)} ${fmt(b1.y)} L ${fmt(tip.x)} ${fmt(tip.y)} L ${fmt(b2.x)} ${fmt(b2.y)}`
      );
    }

    return { shaftPaths: shaft, headPaths: head };
  }, [tail, tip, resolvedBend, resolvedSeed, variant, arrowhead, strokeWidth, iterations, roughness]);

  return (
    <span
      ref={containerRef}
      className={`relative inline-block overflow-visible ${className}`}
    >
      {/* ── RoughArrow SVG Layer ────────────────────────────────────── */}
      <svg
        aria-hidden="true"
        className="absolute top-0 left-0 w-full h-full pointer-events-none overflow-visible z-20"
      >
        {/* Shaft / Stem */}
        {shaftPaths.map((d, idx) => (
          <motion.path
            key={`shaft-${idx}`}
            d={d}
            stroke={color}
            strokeWidth={idx === 0 ? strokeWidth : strokeWidth * 0.85}
            fill="none"
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={animate ? { pathLength: 0 } : false}
            animate={{ pathLength: inView ? 1 : 0 }}
            transition={animate ? {
              duration: (animationDuration * 0.65) / 1000,
              delay: animationDelay / 1000,
              ease: [0.25, 0.1, 0.25, 1],
            } : INSTANT}
          />
        ))}

        {/* Arrowhead */}
        {headPaths.map((d, idx) => (
          <motion.path
            key={`head-${idx}`}
            d={d}
            stroke={color}
            strokeWidth={idx === 0 ? strokeWidth : strokeWidth * 0.85}
            fill={arrowhead === "filled" ? color : "none"}
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={animate ? { pathLength: 0, opacity: 0 } : false}
            animate={{
              pathLength: inView ? 1 : 0,
              opacity: inView ? 1 : 0,
            }}
            transition={animate ? {
              duration: (animationDuration * 0.35) / 1000,
              delay: (animationDelay + animationDuration * 0.55) / 1000,
              ease: [0.25, 0.1, 0.25, 1],
            } : INSTANT}
          />
        ))}
      </svg>

      {/* ── Handwritten Callout Label (Straight at Tail) ───────────── */}
      {label && (
        // Position on a plain span: framer-motion owns `transform` on the animated span (y/scale), so a
        // positioning translate there would be dropped and the label would hang off its top-left corner.
        <span
          className="absolute pointer-events-none z-30"
          style={{ left: labelPos.x, top: labelPos.y, transform: labelTransform, transformOrigin: "center center" }}
        >
          <motion.span
            initial={animate ? { opacity: 0, scale: 0.9, y: 4 } : false}
            animate={{
              opacity: inView ? 1 : 0,
              scale: inView ? 1 : 0.9,
              y: inView ? 0 : 4,
            }}
            transition={animate ? {
              duration: 0.35,
              delay: (animationDelay + animationDuration * 0.7) / 1000,
              ease: [0.16, 1, 0.3, 1],
            } : INSTANT}
            className={`block whitespace-nowrap select-none ${labelFontClassMap[labelFont] || labelFontClassMap.caveat} leading-none ${labelClassName}`}
            style={{
              color: labelColor || color,
              fontSize: labelFontSize ? `${labelFontSize}px` : undefined,
              fontWeight: labelFontWeight || undefined,
            }}
          >
            {label}
          </motion.span>
        </span>
      )}

      {/* ── Target Content ───────────────────────────────────────────── */}
      {children && (
        <span className={`relative z-10 ${textClassName}`}>{children}</span>
      )}
    </span>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { useRoughMotion } from "./useRoughMotion";
import { annotate } from "rough-notation";
import type { RoughAnnotation } from "rough-notation/lib/model";

export type BoxVariant = "single" | "double";

export interface RoughBoxProps {
  children: React.ReactNode;
  /** Box frame style variant: 'single' (1 stroke loop) | 'double' (2 authentic sketch loops) (default: 'double') */
  variant?: BoxVariant;
  /** Frame stroke color (default: "#10B981" Emerald) */
  color?: string;
  /** Frame stroke thickness in pixels (default: 2) */
  strokeWidth?: number;
  /** Explicit stroke iterations override (if not set, inferred from variant: single=1, double=2) */
  iterations?: number;
  /** Drawing animation duration in milliseconds (default: 800) */
  animationDuration?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Delay before animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Padding around the content in px: [top, right, bottom, left] or number (default: [4, 8, 4, 8]) */
  padding?: number | [number, number] | [number, number, number, number];
  /** Horizontal padding helper in px (convenience override for padding[1] and padding[3]) */
  paddingX?: number;
  /** Vertical padding helper in px (convenience override for padding[0] and padding[2]) */
  paddingY?: number;
  /** Whether multi-line text blocks wrap with continuous per-line box frames (default: false) */
  multiline?: boolean;
  /** Additional CSS class names for the container */
  className?: string;
  /** Additional CSS class names for the inner text */
  textClassName?: string;
}

export function RoughBox({
  children,
  variant = "double",
  color = "#10B981",
  strokeWidth = 2,
  iterations,
  animationDuration = 800,
  animate: animateProp = true,
  animationDelay = 0,
  padding,
  paddingX,
  paddingY,
  multiline = false,
  className = "",
  textClassName = "",
}: RoughBoxProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const annotationRef = useRef<RoughAnnotation | null>(null);
  const [inView, setInView] = useState(!animate);

  // Viewport intersection observer to ensure drawing animation triggers when scrolled into view
  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  // rough-notation lifecycle for RoughBox
  useEffect(() => {
    const el = textRef.current;
    if (!el || !inView) return undefined;

    let isMounted = true;

    const createAnnotation = () => {
      if (!isMounted || !textRef.current) return;

      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }

      // Resolve final iterations: user override or derived from variant
      const finalIterations =
        iterations ?? (variant === "double" ? 2 : 1);

      // Resolve symmetric or directional padding [top, right, bottom, left]
      let resolvedPadding: [number, number, number, number] = [4, 8, 4, 8];
      if (padding !== undefined) {
        if (typeof padding === "number") {
          resolvedPadding = [padding, padding, padding, padding];
        } else if (Array.isArray(padding)) {
          if (padding.length === 2) {
            resolvedPadding = [padding[0], padding[1], padding[0], padding[1]];
          } else if (padding.length === 4) {
            resolvedPadding = [...padding];
          }
        }
      }

      if (paddingX !== undefined) {
        resolvedPadding[1] = paddingX;
        resolvedPadding[3] = paddingX;
      }
      if (paddingY !== undefined) {
        resolvedPadding[0] = paddingY;
        resolvedPadding[2] = paddingY;
      }

      const annotation = annotate(textRef.current, {
        type: "box",
        color,
        strokeWidth,
        padding: resolvedPadding,
        animate,
        animationDuration,
        iterations: finalIterations,
        multiline,
      });

      annotationRef.current = annotation;

      const applySvgLayering = () => {
        const svg = containerRef.current?.querySelector<SVGSVGElement>("svg.rough-annotation");
        if (svg) {
          svg.style.pointerEvents = "none";
        }
      };

      if (animationDelay > 0) {
        const timer = setTimeout(() => {
          if (isMounted && annotationRef.current) {
            annotation.show();
            applySvgLayering();
          }
        }, animationDelay);
        return () => clearTimeout(timer);
      } else {
        annotation.show();
        applySvgLayering();
      }
      return undefined;
    };

    if (typeof document !== "undefined" && document.fonts?.ready) {
      document.fonts.ready.then(createAnnotation).catch(createAnnotation);
    } else {
      createAnnotation();
    }

    return () => {
      isMounted = false;
      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }
    };
  }, [
    inView,
    variant,
    color,
    strokeWidth,
    iterations,
    animationDuration,
    animate,
    animationDelay,
    padding,
    paddingX,
    paddingY,
    multiline,
    children,
  ]);

  return (
    <span
      ref={containerRef}
      className={`relative ${multiline ? "inline" : "inline-block"} [&>.rough-annotation]:pointer-events-none ${className}`}
    >
      <span ref={textRef} className={`relative z-10 inline ${textClassName}`}>{children}</span>
    </span>
  );
}

"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { INSTANT, useRoughMotion } from "./useRoughMotion";
import { motion } from "framer-motion";

export type BracketSide = "left" | "right" | "top" | "bottom" | "both";
export type BracketStyle = "curly" | "square";

export interface RoughBracketProps {
  children: React.ReactNode;
  /** Bracket placement side: 'left' | 'right' | 'top' | 'bottom' | 'both' (default: 'left') */
  side?: BracketSide;
  /** Alias for side prop to maintain backward compatibility */
  brackets?: BracketSide;
  /** Bracket style: 'curly' ({ }) or 'square' ([ ]) (default: 'curly') */
  bracketStyle?: BracketStyle;
  /** Stroke color (default: "#F59E0B" Cyber Amber) */
  color?: string;
  /** Stroke thickness in pixels (default: 2) */
  strokeWidth?: number;
  /** Drawing animation duration in milliseconds (default: 750) */
  animationDuration?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Delay before animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Gap / clearance between bracket and multiline text in px (default: 10) */
  bracketPadding?: number;
  /** Container HTML element tag: 'div' or 'span' (default: 'div' for multiline blocks) */
  as?: "div" | "span";
  /** Additional CSS class names for the container */
  className?: string;
  /** Additional CSS class names for the inner text / content */
  textClassName?: string;
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

/**
 * Builds an authentic, single-stroke continuous path for a vertical bracket (left or right side).
 * Dynamically scales the straight stems to any multiline height while preserving exact curve radii.
 */
function buildVerticalPath(
  side: "left" | "right",
  style: BracketStyle,
  height: number
): string {
  const H = Math.max(height, 24);
  const padY = Math.min(4, H * 0.04);
  const yStart = padY;
  const yEnd = H - padY;
  const yMid = (yStart + yEnd) / 2;
  const span = yEnd - yStart;

  if (style === "curly") {
    // Radius of top/bottom hooks and center cusp
    const r = Math.max(3.5, Math.min(7, (yMid - yStart) * 0.28));

    if (side === "left") {
      const hookX = 14; // near text
      const spineX = 8; // vertical spine
      const tipX = 2; // outward pointing cusp
      const dx1 = (hookX - spineX) * 0.3;
      const dx2 = (spineX - tipX) * 0.3;

      return [
        `M ${hookX} ${yStart.toFixed(1)}`,
        `C ${(hookX - dx1).toFixed(1)} ${yStart.toFixed(1)}, ${spineX} ${(yStart + r * 0.45).toFixed(1)}, ${spineX} ${(yStart + r).toFixed(1)}`,
        `L ${spineX} ${(yMid - r).toFixed(1)}`,
        `C ${spineX} ${(yMid - r * 0.45).toFixed(1)}, ${(tipX + dx2).toFixed(1)} ${yMid.toFixed(1)}, ${tipX} ${yMid.toFixed(1)}`,
        `C ${(tipX + dx2).toFixed(1)} ${yMid.toFixed(1)}, ${spineX} ${(yMid + r * 0.45).toFixed(1)}, ${spineX} ${(yMid + r).toFixed(1)}`,
        `L ${spineX} ${(yEnd - r).toFixed(1)}`,
        `C ${spineX} ${(yEnd - r * 0.45).toFixed(1)}, ${(hookX - dx1).toFixed(1)} ${yEnd.toFixed(1)}, ${hookX} ${yEnd.toFixed(1)}`,
      ].join(" ");
    } else {
      // Right side curly
      const hookX = 2; // near text
      const spineX = 8; // vertical spine
      const tipX = 14; // outward pointing cusp
      const dx1 = (spineX - hookX) * 0.3;
      const dx2 = (tipX - spineX) * 0.3;

      return [
        `M ${hookX} ${yStart.toFixed(1)}`,
        `C ${(hookX + dx1).toFixed(1)} ${yStart.toFixed(1)}, ${spineX} ${(yStart + r * 0.45).toFixed(1)}, ${spineX} ${(yStart + r).toFixed(1)}`,
        `L ${spineX} ${(yMid - r).toFixed(1)}`,
        `C ${spineX} ${(yMid - r * 0.45).toFixed(1)}, ${(tipX - dx2).toFixed(1)} ${yMid.toFixed(1)}, ${tipX} ${yMid.toFixed(1)}`,
        `C ${(tipX - dx2).toFixed(1)} ${yMid.toFixed(1)}, ${spineX} ${(yMid + r * 0.45).toFixed(1)}, ${spineX} ${(yMid + r).toFixed(1)}`,
        `L ${spineX} ${(yEnd - r).toFixed(1)}`,
        `C ${spineX} ${(yEnd - r * 0.45).toFixed(1)}, ${(hookX + dx1).toFixed(1)} ${yEnd.toFixed(1)}, ${hookX} ${yEnd.toFixed(1)}`,
      ].join(" ");
    }
  }

  // Square style
  const rCorner = Math.min(3, span * 0.05);
  if (side === "left") {
    const armX = 14;
    const spineX = 3;
    return [
      `M ${armX} ${yStart.toFixed(1)}`,
      `L ${(spineX + rCorner).toFixed(1)} ${yStart.toFixed(1)}`,
      `Q ${spineX} ${yStart.toFixed(1)}, ${spineX} ${(yStart + rCorner).toFixed(1)}`,
      `L ${spineX} ${(yEnd - rCorner).toFixed(1)}`,
      `Q ${spineX} ${yEnd.toFixed(1)}, ${(spineX + rCorner).toFixed(1)} ${yEnd.toFixed(1)}`,
      `L ${armX} ${yEnd.toFixed(1)}`,
    ].join(" ");
  } else {
    // Right side square
    const armX = 2;
    const spineX = 13;
    return [
      `M ${armX} ${yStart.toFixed(1)}`,
      `L ${(spineX - rCorner).toFixed(1)} ${yStart.toFixed(1)}`,
      `Q ${spineX} ${yStart.toFixed(1)}, ${spineX} ${(yStart + rCorner).toFixed(1)}`,
      `L ${spineX} ${(yEnd - rCorner).toFixed(1)}`,
      `Q ${spineX} ${yEnd.toFixed(1)}, ${(spineX - rCorner).toFixed(1)} ${yEnd.toFixed(1)}`,
      `L ${armX} ${yEnd.toFixed(1)}`,
    ].join(" ");
  }
}

/**
 * Builds an authentic, single-stroke continuous path for a horizontal bracket (top or bottom side).
 */
function buildHorizontalPath(
  side: "top" | "bottom",
  style: BracketStyle,
  width: number
): string {
  const W = Math.max(width, 24);
  const padX = Math.min(4, W * 0.04);
  const xStart = padX;
  const xEnd = W - padX;
  const xMid = (xStart + xEnd) / 2;
  const span = xEnd - xStart;

  if (style === "curly") {
    const r = Math.max(3.5, Math.min(7, (xMid - xStart) * 0.28));

    if (side === "top") {
      const hookY = 14; // near text
      const spineY = 8; // horizontal spine
      const tipY = 2; // outward pointing cusp
      const dy1 = (hookY - spineY) * 0.3;
      const dy2 = (spineY - tipY) * 0.3;

      return [
        `M ${xStart.toFixed(1)} ${hookY}`,
        `C ${xStart.toFixed(1)} ${(hookY - dy1).toFixed(1)}, ${(xStart + r * 0.45).toFixed(1)} ${spineY}, ${(xStart + r).toFixed(1)} ${spineY}`,
        `L ${(xMid - r).toFixed(1)} ${spineY}`,
        `C ${(xMid - r * 0.45).toFixed(1)} ${spineY}, ${xMid.toFixed(1)} ${(tipY + dy2).toFixed(1)}, ${xMid.toFixed(1)} ${tipY}`,
        `C ${xMid.toFixed(1)} ${(tipY + dy2).toFixed(1)}, ${(xMid + r * 0.45).toFixed(1)} ${spineY}, ${(xMid + r).toFixed(1)} ${spineY}`,
        `L ${(xEnd - r).toFixed(1)} ${spineY}`,
        `C ${(xEnd - r * 0.45).toFixed(1)} ${spineY}, ${xEnd.toFixed(1)} ${(hookY - dy1).toFixed(1)}, ${xEnd.toFixed(1)} ${hookY}`,
      ].join(" ");
    } else {
      // Bottom side curly
      const hookY = 2; // near text
      const spineY = 8; // horizontal spine
      const tipY = 14; // outward pointing cusp
      const dy1 = (spineY - hookY) * 0.3;
      const dy2 = (tipY - spineY) * 0.3;

      return [
        `M ${xStart.toFixed(1)} ${hookY}`,
        `C ${xStart.toFixed(1)} ${(hookY + dy1).toFixed(1)}, ${(xStart + r * 0.45).toFixed(1)} ${spineY}, ${(xStart + r).toFixed(1)} ${spineY}`,
        `L ${(xMid - r).toFixed(1)} ${spineY}`,
        `C ${(xMid - r * 0.45).toFixed(1)} ${spineY}, ${xMid.toFixed(1)} ${(tipY - dy2).toFixed(1)}, ${xMid.toFixed(1)} ${tipY}`,
        `C ${xMid.toFixed(1)} ${(tipY - dy2).toFixed(1)}, ${(xMid + r * 0.45).toFixed(1)} ${spineY}, ${(xMid + r).toFixed(1)} ${spineY}`,
        `L ${(xEnd - r).toFixed(1)} ${spineY}`,
        `C ${(xEnd - r * 0.45).toFixed(1)} ${spineY}, ${xEnd.toFixed(1)} ${(hookY + dy1).toFixed(1)}, ${xEnd.toFixed(1)} ${hookY}`,
      ].join(" ");
    }
  }

  // Square style
  const rCorner = Math.min(3, span * 0.05);
  if (side === "top") {
    const armY = 14;
    const spineY = 3;
    return [
      `M ${xStart.toFixed(1)} ${armY}`,
      `L ${xStart.toFixed(1)} ${(spineY + rCorner).toFixed(1)}`,
      `Q ${xStart.toFixed(1)} ${spineY}, ${(xStart + rCorner).toFixed(1)} ${spineY}`,
      `L ${(xEnd - rCorner).toFixed(1)} ${spineY}`,
      `Q ${xEnd.toFixed(1)} ${spineY}, ${xEnd.toFixed(1)} ${(spineY + rCorner).toFixed(1)}`,
      `L ${xEnd.toFixed(1)} ${armY}`,
    ].join(" ");
  } else {
    // Bottom side square
    const armY = 2;
    const spineY = 13;
    return [
      `M ${xStart.toFixed(1)} ${armY}`,
      `L ${xStart.toFixed(1)} ${(spineY - rCorner).toFixed(1)}`,
      `Q ${xStart.toFixed(1)} ${spineY}, ${(xStart + rCorner).toFixed(1)} ${spineY}`,
      `L ${(xEnd - rCorner).toFixed(1)} ${spineY}`,
      `Q ${xEnd.toFixed(1)} ${spineY}, ${xEnd.toFixed(1)} ${(spineY - rCorner).toFixed(1)}`,
      `L ${xEnd.toFixed(1)} ${armY}`,
    ].join(" ");
  }
}

export function RoughBracket({
  children,
  side = "left",
  brackets,
  bracketStyle = "curly",
  color = "#F59E0B",
  strokeWidth = 2,
  animationDuration = 750,
  animate: animateProp = true,
  animationDelay = 0,
  bracketPadding = 10,
  as: Component = "div",
  className = "",
  textClassName = "",
}: RoughBracketProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(!animate);
  const [dimensions, setDimensions] = useState<{ width: number; height: number }>({
    width: 0,
    height: 0,
  });

  const activeSide: BracketSide = side || brackets || "left";

  // Measure container dimensions for dynamic multiline path calculation
  useIsomorphicLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return undefined;

    const measure = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        setDimensions({
          width: Math.round(rect.width),
          height: Math.round(rect.height),
        });
      }
    };

    measure();

    if (typeof document !== "undefined" && document.fonts?.ready) {
      document.fonts.ready.then(measure).catch(measure);
    }

    if (typeof ResizeObserver === "undefined") return undefined;
    const ro = new ResizeObserver(() => measure());
    ro.observe(el);
    return () => ro.disconnect();
  }, [children, activeSide, bracketStyle]);

  // Viewport intersection observer to trigger drawing smoothly on scroll entry
  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  const h = dimensions.height || 48;
  const w = dimensions.width || 120;
  const bracketThickness = 16; // width of vertical SVG or height of horizontal SVG

  // Calculate clean directional padding to prevent multiline text collision
  const stylePadding: React.CSSProperties = {};
  if (activeSide === "left") {
    stylePadding.paddingLeft = bracketThickness + bracketPadding;
  } else if (activeSide === "right") {
    stylePadding.paddingRight = bracketThickness + bracketPadding;
  } else if (activeSide === "both") {
    stylePadding.paddingLeft = bracketThickness + bracketPadding;
    stylePadding.paddingRight = bracketThickness + bracketPadding;
  } else if (activeSide === "top") {
    stylePadding.paddingTop = bracketThickness + bracketPadding;
  } else if (activeSide === "bottom") {
    stylePadding.paddingBottom = bracketThickness + bracketPadding;
  }

  // Animation settings for fluid, hardware-accelerated single-stroke draw
  const pathTransition = {
    pathLength: {
      duration: animationDuration / 1000,
      delay: animationDelay / 1000,
      ease: [0.25, 0.1, 0.25, 1],
    },
    opacity: { duration: 0.05 },
  };

  const renderSingleBracket = (
    placement: "left" | "right" | "top" | "bottom",
    keySuffix = ""
  ) => {
    const isVertical = placement === "left" || placement === "right";
    const pathD = isVertical
      ? buildVerticalPath(placement, bracketStyle, h)
      : buildHorizontalPath(placement, bracketStyle, w);

    const svgWidth = isVertical ? bracketThickness : w;
    const svgHeight = isVertical ? h : bracketThickness;

    const positioningClass =
      placement === "left"
        ? "left-0 top-0 bottom-0"
        : placement === "right"
        ? "right-0 top-0 bottom-0"
        : placement === "top"
        ? "top-0 left-0 right-0"
        : "bottom-0 left-0 right-0";

    return (
      <svg
        key={`bracket-${placement}${keySuffix}`}
        aria-hidden="true"
        className={`absolute pointer-events-none z-10 overflow-visible ${positioningClass}`}
        style={{
          width: svgWidth,
          height: svgHeight,
        }}
        viewBox={`0 0 ${svgWidth} ${svgHeight}`}
        fill="none"
      >
        <motion.path
          d={pathD}
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={animate ? { pathLength: 0, opacity: 0 } : false}
          animate={inView ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
          transition={animate ? pathTransition : INSTANT}
        />
      </svg>
    );
  };

  return (
    <Component
      ref={containerRef}
      className={`relative inline-block w-fit max-w-full ${className}`}
      style={stylePadding}
    >
      {/* ── Single continuous vector bracket stroke(s) ── */}
      {activeSide === "both" ? (
        <>
          {renderSingleBracket("left", "-l")}
          {renderSingleBracket("right", "-r")}
        </>
      ) : (
        renderSingleBracket(activeSide)
      )}

      {/* ── Multiline Content ── */}
      <div className={`relative z-10 ${textClassName}`}>{children}</div>
    </Component>
  );
}

"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { useRoughMotion } from "./useRoughMotion";
import { annotate } from "rough-notation";
import type { RoughAnnotation } from "rough-notation/lib/model";

export interface RoughCircleProps {
  children: React.ReactNode;
  /** Circle stroke color (default: "#6366F1") */
  color?: string;
  /** Stroke thickness in pixels (default: 2) */
  strokeWidth?: number;
  /** Horizontal padding around the content in px (default: 22 for generous, symmetric breathing room) */
  paddingX?: number;
  /** Vertical padding around the content in px (default: 10) */
  paddingY?: number;
  /** Drawing animation duration in milliseconds (default: 800) */
  animationDuration?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Number of sketchy stroke loops (default: 2 for authentic hand-drawn look) */
  iterations?: number;
  /** Delay before animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Additional CSS class names for the wrapping span */
  className?: string;
  /** Additional CSS class names for the inner text content */
  textClassName?: string;
  /**
   * Draw the circle to this fraction (0–1) instead of playing the timed
   * animation, e.g. to drive it from a video timeline.
   */
  progress?: number;
  /** Fixes the hand-drawn shape when `progress` is used, so every render matches (default: 1) */
  seed?: number;
}

const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

export function RoughCircle({
  children,
  color = "#6366F1",
  strokeWidth = 2,
  paddingX = 22,
  paddingY = 10,
  animationDuration = 800,
  animate: animateProp = true,
  iterations = 2,
  animationDelay = 0,
  className = "",
  textClassName = "",
  progress,
  seed = 1,
}: RoughCircleProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const annotationRef = useRef<RoughAnnotation | null>(null);
  const driven = progress !== undefined;
  const [inView, setInView] = useState(!animate || driven);

  // Viewport intersection observer to ensure animation plays when scrolled into view
  useEffect(() => {
    if (!animate || driven) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate, driven]);

  // Rough-notation annotation lifecycle
  useEffect(() => {
    const el = textRef.current;
    if (driven || !el || !inView) return undefined;

    let isMounted = true;

    const createAnnotation = () => {
      if (!isMounted || !textRef.current) return;

      // Clean up previous instance if already present
      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }

      // Symmetric padding [top, right, bottom, left]
      // Equal left and right padding guarantees identical space and curvature on both sides
      const padding: [number, number, number, number] = [
        paddingY,
        paddingX,
        paddingY,
        paddingX,
      ];

      const annotation = annotate(textRef.current, {
        type: "circle",
        color,
        strokeWidth,
        padding,
        animate,
        animationDuration,
        iterations,
      });

      annotationRef.current = annotation;

      const applySvgLayering = () => {
        const svg = containerRef.current?.querySelector<SVGSVGElement>("svg.rough-annotation");
        if (svg) {
          svg.style.pointerEvents = "none";
        }
      };

      if (animationDelay > 0) {
        const timer = setTimeout(() => {
          if (isMounted && annotationRef.current) {
            annotation.show();
            applySvgLayering();
          }
        }, animationDelay);
        return () => clearTimeout(timer);
      } else {
        annotation.show();
        applySvgLayering();
      }
      return undefined;
    };

    // Synchronize with font-ready to guarantee precise text bounding box
    if (typeof document !== "undefined" && document.fonts?.ready) {
      document.fonts.ready.then(createAnnotation).catch(createAnnotation);
    } else {
      createAnnotation();
    }

    return () => {
      isMounted = false;
      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }
    };
  }, [
    inView,
    color,
    strokeWidth,
    paddingX,
    paddingY,
    animationDuration,
    animate,
    iterations,
    animationDelay,
    children,
    driven,
  ]);

  // Driven drawing: build the annotation once without its timed animation,
  // then reveal the stroke by `progress` on every render, before paint.
  useIsomorphicLayoutEffect(() => {
    if (!driven || !textRef.current) return;

    if (!annotationRef.current) {
      const annotation = annotate(textRef.current, {
        type: "circle",
        color,
        strokeWidth,
        padding: [paddingY, paddingX, paddingY, paddingX],
        animate: false,
        iterations,
      });
      // rough-notation picks a random seed per annotation; pin it so every render draws the same shape
      (annotation as unknown as { _seed: number })._seed = seed;
      annotation.show();
      annotationRef.current = annotation;
      const svg = containerRef.current?.querySelector<SVGSVGElement>("svg.rough-annotation");
      if (svg) svg.style.pointerEvents = "none";
    }

    const paths = Array.from(
      containerRef.current?.querySelectorAll<SVGPathElement>("svg.rough-annotation path") ?? []
    );
    const lengths = paths.map((p) => p.getTotalLength());
    let remaining = Math.min(1, Math.max(0, progress ?? 0)) * lengths.reduce((a, b) => a + b, 0);
    paths.forEach((path, i) => {
      const shown = Math.min(lengths[i], Math.max(0, remaining));
      remaining -= lengths[i];
      path.style.strokeDasharray = `${lengths[i]}`;
      path.style.strokeDashoffset = `${lengths[i] - shown}`;
    });
  });

  useEffect(() => {
    if (!driven) return undefined;
    return () => {
      annotationRef.current?.remove();
      annotationRef.current = null;
    };
  }, [driven]);

  return (
    <span
      ref={containerRef}
      className={`relative inline-block [&>.rough-annotation]:pointer-events-none ${className}`}
    >
      <span ref={textRef} className={`relative z-10 inline ${textClassName}`}>{children}</span>
    </span>
  );
}

