export interface RoughUnderlineProps {
  children: React.ReactNode;
  /** Underline mode: 'single' | 'double' | 'wavy' (default: 'single') */
  variant?: UnderlineVariant;
  /** Underline stroke color (default: "#6366F1") */
  color?: string;
  /** Stroke thickness in pixels (default: 2) */
  strokeWidth?: number;
  /** Drawing animation duration in milliseconds (default: 650) */
  animationDuration?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Delay before animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Additional CSS class names for the container */
  className?: string;
  /** Additional CSS class names for the inner text */
  textClassName?: string;
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

export function RoughUnderline({
  children,
  variant = "single",
  color = "#6366F1",
  strokeWidth = 2,
  animationDuration = 650,
  animate: animateProp = true,
  animationDelay = 0,
  className = "",
  textClassName = "",
}: RoughUnderlineProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const annotationRef = useRef<RoughAnnotation | null>(null);
  const [inView, setInView] = useState(!animate);
  const [width, setWidth] = useState<number>(0);

  // Viewport intersection observer to trigger drawing when scrolled into view
  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  // Measure container width for dynamic continuous wavy underline
  useIsomorphicLayoutEffect(() => {
    if (variant !== "wavy") return undefined;
    const el = containerRef.current;
    if (!el) return undefined;

    const measure = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0) {
        setWidth(rect.width);
      }
    };

    measure();

    if (typeof ResizeObserver === "undefined") return undefined;
    const ro = new ResizeObserver(() => measure());
    ro.observe(el);
    return () => ro.disconnect();
  }, [children, variant]);

  // rough-notation lifecycle for 'single' and 'double' variants
  useEffect(() => {
    if (variant === "wavy") {
      if (annotationRef.current) {
        annotationRef.current.remove();
        annotationRef.current = null;
      }
      return undefined;
    }

    const el = textRef.current;
    if (!el || !inView) return undefined;

    let isMounted = true;

    const createAnnotation = () => {
      if (!isMounted || !textRef.current) return;

      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }

      const iterations = variant === "single" ? 1 : 2;

      const annotation = annotate(textRef.current, {
        type: "underline",
        color,
        strokeWidth,
        padding: [0, 2, 4, 2],
        animate,
        animationDuration,
        iterations,
        multiline: true,
      });

      annotationRef.current = annotation;

      if (animationDelay > 0) {
        const timer = setTimeout(() => {
          if (isMounted && annotationRef.current) {
            annotation.show();
          }
        }, animationDelay);
        return () => clearTimeout(timer);
      } else {
        annotation.show();
      }
      return undefined;
    };

    if (typeof document !== "undefined" && document.fonts?.ready) {
      document.fonts.ready.then(createAnnotation).catch(createAnnotation);
    } else {
      createAnnotation();
    }

    return () => {
      isMounted = false;
      if (annotationRef.current) {
        try {
          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }
    };
  }, [
    inView,
    variant,
    color,
    strokeWidth,
    animationDuration,
    animate,
    animationDelay,
    children,
  ]);

  // Generate dynamic, seamless wavy underline across the exact measured text width
  const w = Math.max(width || 120, 24);
  const wavelength = 16;
  const waveCycles = Math.max(2, Math.round((w - 4) / wavelength));
  const waveStep = (w - 4) / waveCycles;

  let wavyPath = `M 2 7`;
  for (let i = 0; i < waveCycles; i++) {
    const xStart = 2 + i * waveStep;
    const xMid = xStart + waveStep / 2;
    const xEnd = xStart + waveStep;
    const yPeak = i % 2 === 0 ? 3 : 11;
    wavyPath += ` Q ${xMid.toFixed(1)} ${yPeak}, ${xEnd.toFixed(1)} 7`;
  }

  return (
    <span
      ref={containerRef}
      className={`relative inline ${className}`}
    >
      <span ref={textRef} className={`relative z-10 ${textClassName}`}>
        {children}
      </span>

      {/* Wavy Underline: Handcrafted fluid wave with buttery smooth 60fps Framer Motion stroke */}
      {variant === "wavy" && (
        <svg
          aria-hidden="true"
          className="absolute left-0 right-0 -bottom-2 w-full h-3.5 pointer-events-none -z-10 overflow-visible"
          viewBox={`0 0 ${w} 14`}
          fill="none"
        >
          <motion.path
            d={wavyPath}
            stroke={color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={animate ? { pathLength: 0, opacity: 0 } : false}
            animate={inView ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
            transition={animate ? {
              pathLength: {
                duration: animationDuration / 1000,
                delay: animationDelay / 1000,
                ease: [0.25, 0.1, 0.25, 1],
              },
              opacity: { duration: 0.05 },
            } : INSTANT}
          />
        </svg>
      )}
    </span>
  );
}

"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { INSTANT, useRoughMotion } from "./useRoughMotion";
import { motion } from "framer-motion";

export type CheckMark = "check" | "cross";
export type CheckSide = "left" | "right";

export interface RoughCheckProps {
  children: React.ReactNode;
  /** Mark drawn in the margin: 'check' (✓) or 'cross' (✗) (default: 'check') */
  mark?: CheckMark;
  /** Which margin the mark sits in (default: 'left') */
  side?: CheckSide;
  /** Whether the mark is drawn. Flip it to draw / erase the mark, e.g. for a checklist (default: true) */
  checked?: boolean;
  /** Stroke color (default: emerald for 'check', rose for 'cross') */
  color?: string;
  /** Stroke thickness in pixels (default: 2.5) */
  strokeWidth?: number;
  /** Mark size in pixels (default: ~90% of the first line's height) */
  size?: number;
  /** Space between the mark and the content in pixels (default: 10) */
  gap?: number;
  /** Total drawing animation duration in milliseconds (default: 500) */
  animationDuration?: number;
  /** Whether the mark animates into view (default: true) */
  animate?: boolean;
  /** Delay before animation starts in milliseconds (default: 0) */
  animationDelay?: number;
  /** Container HTML element tag (default: 'div', so each line is its own row) */
  as?: "div" | "span" | "li";
  /** Additional CSS class names for the container */
  className?: string;
  /** Additional CSS class names for the content */
  textClassName?: string;
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

/**
 * Strokes for each mark in a 0–100 box, in drawing order.
 * The tick's long stroke bows a little, the way a wrist flicks it;
 * the cross arms overshoot and lean, like a quick margin mark.
 */
const MARK_STROKES: Record<CheckMark, string[]> = {
  check: ["M 8 54 Q 22 66 37 86 Q 58 44 96 10"],
  cross: ["M 14 12 Q 46 44 88 90", "M 86 10 Q 52 50 12 88"],
};

export function RoughCheck({
  children,
  mark = "check",
  side = "left",
  checked = true,
  color,
  strokeWidth = 2.5,
  size,
  gap = 10,
  animationDuration = 500,
  animate: animateProp = true,
  animationDelay = 0,
  as: Component = "div",
  className = "",
  textClassName = "",
}: RoughCheckProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const [lineHeight, setLineHeight] = useState(24);
  const [inView, setInView] = useState(!animate);

  // Size the mark from the first line so it sits beside it in any font size
  useIsomorphicLayoutEffect(() => {
    const el = textRef.current;
    if (!el) return undefined;

    const measure = () => {
      const style = window.getComputedStyle(el);
      const lh = parseFloat(style.lineHeight);
      const fs = parseFloat(style.fontSize) || 16;
      setLineHeight(Number.isFinite(lh) ? lh : fs * 1.2);
    };

    measure();
    if (typeof document !== "undefined" && document.fonts?.ready) {
      document.fonts.ready.then(measure).catch(() => {});
    }
    return undefined;
  }, [children]);

  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  const markSize = size ?? Math.round(lineHeight * 0.9);
  const strokeColor = color ?? (mark === "check" ? "#10B981" : "#F43F5E");
  const strokes = MARK_STROKES[mark];
  const visible = inView && checked;
  const strokeDuration = animationDuration / 1000 / strokes.length;
  // viewBox is 0–100, so scale the stroke back to real pixels
  const scaledStroke = (strokeWidth * 100) / markSize;

  return (
    <Component
      ref={containerRef as React.Ref<never>}
      className={`relative ${Component === "span" ? "inline-block" : "block"} ${className}`}
      style={side === "left" ? { paddingLeft: markSize + gap } : { paddingRight: markSize + gap }}
    >
      <svg
        aria-hidden="true"
        viewBox="0 0 100 100"
        fill="none"
        className="absolute pointer-events-none overflow-visible z-20"
        style={{
          width: markSize,
          height: markSize,
          top: (lineHeight - markSize) / 2,
          [side === "left" ? "left" : "right"]: 0,
        }}
      >
        {strokes.map((d, i) => (
          <motion.path
            key={`${mark}-${i}`}
            d={d}
            stroke={strokeColor}
            strokeWidth={scaledStroke}
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={animate ? { pathLength: 0, opacity: 0 } : false}
            animate={visible ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
            transition={animate ? {
              pathLength: {
                duration: strokeDuration,
                // erase in reverse order, draw in forward order
                delay: visible
                  ? animationDelay / 1000 + i * strokeDuration
                  : (strokes.length - 1 - i) * strokeDuration * 0.5,
                ease: [0.3, 0.1, 0.2, 1],
              },
              opacity: {
                duration: 0.01,
                delay: visible
                  ? animationDelay / 1000 + i * strokeDuration
                  : strokeDuration * strokes.length,
              },
            } : INSTANT}
          />
        ))}
      </svg>
      <span ref={textRef} className={`relative z-10 ${textClassName}`}>
        {children}
      </span>
    </Component>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { INSTANT, useRoughMotion } from "./useRoughMotion";
import { motion } from "framer-motion";
import type { ArrowLabelFont, ArrowPlacement } from "./RoughArrow";

export type StickyPlacement = ArrowPlacement;
export type StickyPin = "tape" | "pin" | "none";
export type StickyFont = ArrowLabelFont;

export interface RoughStickyProps {
  /** Element the note is pinned next to (optional; without it the note renders on its own) */
  children?: React.ReactNode;
  /** Handwritten text on the note */
  note: React.ReactNode;
  /** Where the note sits relative to the target (default: "top-right") */
  placement?: StickyPlacement;
  /** How the note is attached: 'tape' strip, push 'pin', or 'none' (default: "tape") */
  pin?: StickyPin;
  /** Paper color (default: "#FDE68A" sticky yellow) */
  paper?: string;
  /** Ink color for the handwritten text (default: "#3B2A14") */
  color?: string;
  /** Handwriting font: 'caveat' | 'reenie-beanie' | 'kalam' (default: "caveat") */
  font?: StickyFont;
  /** Font size in pixels (default: 20) */
  fontSize?: number;
  /** Tilt in degrees; negative leans left (default: -4, mirrored for left-side placements) */
  rotate?: number;
  /** Note width in pixels (default: 150) */
  width?: number;
  /** Gap between note and target in pixels; negative overlaps the target (default: 6) */
  offset?: number;
  /** Whether the note slaps on when scrolled into view (default: true) */
  animate?: boolean;
  /** Duration of the slap-on animation in milliseconds (default: 550) */
  animationDuration?: number;
  /** Delay before the note appears in milliseconds (default: 0) */
  animationDelay?: number;
  /** Additional CSS class names for the container */
  className?: string;
  /** Additional CSS class names for the target content */
  textClassName?: string;
  /** Additional CSS class names for the note itself */
  noteClassName?: string;
}

const fontClassMap: Record<StickyFont, string> = {
  caveat: "font-[family-name:var(--font-caveat,'Caveat'),cursive]",
  "reenie-beanie": "font-[family-name:'Reenie_Beanie',cursive] tracking-wide",
  kalam: "font-[family-name:'Kalam',cursive]",
};

/** Anchor the note's outer box around the target; the tilt lives on the inner box. */
function placementStyle(placement: StickyPlacement, offset: number): React.CSSProperties {
  const out = `calc(100% + ${offset}px)`;
  switch (placement) {
    case "top":
      return { bottom: out, left: "50%", transform: "translateX(-50%)" };
    case "bottom":
      return { top: out, left: "50%", transform: "translateX(-50%)" };
    case "left":
      return { right: out, top: "50%", transform: "translateY(-50%)" };
    case "right":
      return { left: out, top: "50%", transform: "translateY(-50%)" };
    case "top-left":
      return { bottom: out, right: out };
    case "bottom-left":
      return { top: out, right: out };
    case "bottom-right":
      return { top: out, left: out };
    case "top-right":
    default:
      return { bottom: out, left: out };
  }
}

export function RoughSticky({
  children,
  note,
  placement = "top-right",
  pin = "tape",
  paper = "#FDE68A",
  color = "#3B2A14",
  font = "caveat",
  fontSize = 20,
  rotate,
  width = 150,
  offset = 6,
  animate: animateProp = true,
  animationDuration = 550,
  animationDelay = 0,
  className = "",
  textClassName = "",
  noteClassName = "",
}: RoughStickyProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const [inView, setInView] = useState(!animate);

  useEffect(() => {
    if (!animate) {
      setInView(true);
      return undefined;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  // Notes on the left lean the other way so they tilt toward the target
  const leansLeft = placement === "left" || placement === "top-left" || placement === "bottom-left";
  const tilt = rotate ?? (leansLeft ? 4 : -4);

  const noteEl = (
    <motion.span
      className={`relative block select-none leading-tight ${fontClassMap[font] || fontClassMap.caveat} ${noteClassName}`}
      style={{
        width,
        padding: "18px 14px 16px",
        backgroundColor: paper,
        // a soft fold of light across the paper and a curl shadow under the bottom edge
        backgroundImage:
          "linear-gradient(170deg, rgba(255,255,255,0.35) 0%, rgba(255,255,255,0) 38%, rgba(0,0,0,0.05) 100%)",
        boxShadow:
          "0 1px 1px rgba(0,0,0,0.12), 0 10px 14px -8px rgba(0,0,0,0.45), inset 0 -10px 14px -12px rgba(0,0,0,0.25)",
        borderRadius: "2px 2px 6px 3px / 2px 2px 14px 3px",
        color,
        fontSize,
        transformOrigin: pin === "pin" ? "50% 8px" : "50% 0%",
      }}
      initial={animate ? { opacity: 0, scale: 1.18, rotate: tilt * 2.5, y: -10 } : false}
      animate={
        inView
          ? { opacity: 1, scale: 1, rotate: tilt, y: 0 }
          : { opacity: 0, scale: 1.18, rotate: tilt * 2.5, y: -10 }
      }
      transition={animate ? {
        type: "spring",
        bounce: 0.45,
        duration: animationDuration / 1000,
        delay: animationDelay / 1000,
        opacity: { duration: 0.12, delay: animationDelay / 1000 },
      } : INSTANT}
    >
      {pin === "tape" && (
        <span
          aria-hidden="true"
          className="absolute left-1/2 -top-2.5 h-5 w-14"
          style={{
            transform: "translateX(-50%) rotate(-3deg)",
            backgroundColor: "rgba(255,255,255,0.5)",
            boxShadow: "0 1px 2px rgba(0,0,0,0.12)",
            // torn ends on the tape strip
            clipPath:
              "polygon(3% 0, 97% 4%, 100% 30%, 96% 55%, 100% 82%, 97% 100%, 2% 96%, 0 70%, 4% 45%, 0 18%)",
          }}
        />
      )}
      {pin === "pin" && (
        <span
          aria-hidden="true"
          className="absolute left-1/2 top-1 h-3.5 w-3.5 -translate-x-1/2 rounded-full"
          style={{
            background: "radial-gradient(circle at 35% 30%, #fca5a5 0%, #ef4444 45%, #991b1b 100%)",
            boxShadow: "0 2px 3px rgba(0,0,0,0.4)",
          }}
        />
      )}
      <span className="relative block">{note}</span>
    </motion.span>
  );

  if (!children) {
    return (
      <span ref={containerRef} className={`relative inline-block ${className}`}>
        {noteEl}
      </span>
    );
  }

  return (
    <span ref={containerRef} className={`relative inline-block ${className}`}>
      <span className={`relative z-10 ${textClassName}`}>{children}</span>
      <span
        className="absolute z-30 pointer-events-none"
        style={placementStyle(placement, offset)}
      >
        {noteEl}
      </span>
    </span>
  );
}

"use client";

import React, {
  useEffect,
  useId,
  useRef,
  useState,
  useCallback,
} from "react";
import { INSTANT, useRoughMotion } from "./useRoughMotion";
import { motion } from "framer-motion";
import type { Font, Path } from "opentype.js";
import {
  loadHandwritingFont,
  type HandwritingFont,
} from "./handwriting-fonts";

export type { HandwritingFont };

export interface RoughHandwritingProps {
  children?: React.ReactNode;
  /** Handwriting font: 'reenie-beanie' | 'caveat' | 'kalam' (default: 'reenie-beanie') */
  font?: HandwritingFont;
  /** Optional custom URL to a .ttf file to parse with opentype.js */
  fontUrl?: string;
  /** Ink stroke and fill color (default: '#6366F1') */
  color?: string;
  /** Stroke thickness in pixels (default: 1.5) */
  strokeWidth?: number;
  /** Whether the drawing stroke animates into view (default: true) */
  animate?: boolean;
  /** Total animation duration in ms for display mode (default: 1200) */
  animationDuration?: number;
  /** Delay before animation starts in ms (default: 0) */
  animationDelay?: number;
  /** Font size in px used for glyph path generation (default: 40) */
  fontSize?: number;
  /** Maximum number of words allowed (default: 6) */
  maxWords?: number;
  /** Maximum number of characters allowed (default: 50) */
  maxLength?: number;
  /** Enable interactive live-typing mode (default: false) */
  editable?: boolean;
  /** Controlled value in editable mode */
  value?: string;
  /** Default value in editable mode */
  defaultValue?: string;
  /** Placeholder displayed when text is empty in editable mode */
  placeholder?: string;
  /** Callback fired when text changes in editable mode */
  onChange?: (text: string) => void;
  /** Additional CSS class for the container */
  className?: string;
  /** Additional CSS class for the text */
  textClassName?: string;
}


function extractStringFromChildren(children: React.ReactNode): string {
  if (typeof children === "string") return children;
  if (typeof children === "number") return String(children);
  if (Array.isArray(children)) return children.map(extractStringFromChildren).join("");
  if (React.isValidElement(children) && children.props && (children.props as { children?: React.ReactNode }).children) {
    return extractStringFromChildren((children.props as { children?: React.ReactNode }).children);
  }
  return "";
}

function truncateToWordsAndLength(text: string, maxWords: number, maxLength: number): string {
  if (!text) return "";
  let trimmed = text.slice(0, maxLength);
  const words = trimmed.trim().split(/\s+/);
  if (words.length > maxWords) {
    // Reconstruct up to maxWords
    const regex = new RegExp(`^(\\S+\\s+){${maxWords - 1}}\\S+`);
    const match = trimmed.match(regex);
    if (match) {
      trimmed = match[0];
    } else {
      trimmed = words.slice(0, maxWords).join(" ");
    }
  }
  return trimmed;
}

function glyphPathToSvgPath(gp: Path, decimalPlaces = 2): string {
  const factor = 10 ** decimalPlaces;
  const round = (val: number): string => {
    if (!Number.isFinite(val)) return "0";
    return String(Math.round(val * factor) / factor);
  };

  let d = "";
  for (let i = 0; i < gp.commands.length; i++) {
    const cmd = gp.commands[i];
    if (cmd.type === "M") {
      d += `M${round(cmd.x)} ${round(cmd.y)}`;
    } else if (cmd.type === "L") {
      d += `L${round(cmd.x)} ${round(cmd.y)}`;
    } else if (cmd.type === "C") {
      d += `C${round(cmd.x1)} ${round(cmd.y1)} ${round(cmd.x2)} ${round(cmd.y2)} ${round(cmd.x)} ${round(cmd.y)}`;
    } else if (cmd.type === "Q") {
      d += `Q${round(cmd.x1)} ${round(cmd.y1)} ${round(cmd.x)} ${round(cmd.y)}`;
    } else if (cmd.type === "Z") {
      d += "Z";
    }
  }
  return d;
}

interface PathItem {
  id: string;
  d: string;
  char: string;
  isSpace: boolean;
  index: number;
  nonSpaceIndex: number;
}

const fontCssClassMap: Record<HandwritingFont, string> = {
  "reenie-beanie": "font-reenie-beanie",
  caveat: "font-caveat",
  kalam: "font-kalam",
};

export function RoughHandwriting({
  children,
  font = "reenie-beanie",
  fontUrl,
  color = "#6366F1",
  strokeWidth = 1.5,
  animate: animateProp = true,
  animationDuration = 1200,
  animationDelay = 0,
  fontSize = 40,
  maxWords = 6,
  maxLength = 50,
  editable = false,
  value,
  defaultValue,
  placeholder = "Write here...",
  onChange,
  className = "",
  textClassName = "",
}: RoughHandwritingProps) {
  const animate = useRoughMotion(animateProp);
  const containerRef = useRef<HTMLSpanElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const instanceId = useId().replace(/:/g, "");

  // Text state for controlled or uncontrolled usage
  const initialText =
    value !== undefined
      ? value
      : defaultValue !== undefined
      ? defaultValue
      : extractStringFromChildren(children);

  const [text, setText] = useState<string>(() =>
    truncateToWordsAndLength(initialText, maxWords, maxLength)
  );
  const [isFocused, setIsFocused] = useState(false);
  const [loadedFont, setLoadedFont] = useState<Font | null>(null);
  const [inView, setInView] = useState(!animate);

  // Synchronize controlled value
  useEffect(() => {
    if (value !== undefined) {
      setText(truncateToWordsAndLength(value, maxWords, maxLength));
    }
  }, [value, maxWords, maxLength]);

  // Synchronize children change when not in editable mode
  useEffect(() => {
    if (!editable && value === undefined) {
      const extracted = extractStringFromChildren(children);
      setText(truncateToWordsAndLength(extracted, maxWords, maxLength));
    }
  }, [children, editable, value, maxWords, maxLength]);

  // Viewport intersection observer to start animation when in view
  useEffect(() => {
    if (!animate) {
      setInView(true);
      return;
    }
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [animate]);

  // Load the opentype font
  useEffect(() => {
    let active = true;
    loadHandwritingFont(font, fontUrl)
      .then((parsed) => {
        if (active) {
          setLoadedFont(parsed);
        }
      })
      .catch((err) => {
        console.warn("RoughHandwriting: Failed to load font outline, falling back to CSS font:", err);
      });

    return () => {
      active = false;
    };
  }, [font, fontUrl]);

  // Compute SVG paths and bounding box from current text
  const displayText = text || (editable ? placeholder : "");
  const isShowingPlaceholder = !text && editable;

  const { pathItems, viewBox, svgWidth, svgHeight } = React.useMemo(() => {
    if (!loadedFont || !displayText) {
      return {
        pathItems: [] as PathItem[],
        viewBox: "0 0 100 40",
        svgWidth: 100,
        svgHeight: 40,
      };
    }

    const baseline = fontSize * 0.85;
    const items: PathItem[] = [];

    try {
      const glyphPaths = loadedFont.getPaths(displayText, 0, baseline, fontSize);
      const overallPath = loadedFont.getPath(displayText, 0, baseline, fontSize);
      const bb = overallPath.getBoundingBox();
      const bounds = glyphPaths.reduce(
        (current, glyphPath) => {
          const glyphBounds = glyphPath.getBoundingBox();
          return {
            x1: Math.min(current.x1, glyphBounds.x1),
            y1: Math.min(current.y1, glyphBounds.y1),
            x2: Math.max(current.x2, glyphBounds.x2),
            y2: Math.max(current.y2, glyphBounds.y2),
          };
        },
        { x1: bb.x1, y1: bb.y1, x2: bb.x2, y2: bb.y2 }
      );

      let nonSpaceCounter = 0;
      glyphPaths.forEach((gp, idx) => {
        const char = displayText[idx] || "";
        const isSpace = char === " ";
        const pathData = glyphPathToSvgPath(gp, 2);
        items.push({
          id: `${instanceId}-${idx}-${char}`,
          d: pathData,
          char,
          isSpace,
          index: idx,
          nonSpaceIndex: isSpace ? -1 : nonSpaceCounter++,
        });
      });

      // Keep the viewBox clear of the painted stroke as well as the glyph
      // outlines. Large stroke widths can extend past the font's path bounds.
      const strokePadding = Math.max(2, strokeWidth / 2 + 1);
      const paddingX = 6 + strokePadding;
      const paddingY = 8 + strokePadding;
      const minX = bounds.x1 - paddingX;
      const minY = bounds.y1 - paddingY;
      const width = Math.max(20, bounds.x2 - bounds.x1 + paddingX * 2);
      const height = Math.max(20, bounds.y2 - bounds.y1 + paddingY * 2);

      return {
        pathItems: items,
        viewBox: `${minX} ${minY} ${width} ${height}`,
        svgWidth: width,
        svgHeight: height,
      };
    } catch {
      return {
        pathItems: [] as PathItem[],
        viewBox: "0 0 100 40",
        svgWidth: 100,
        svgHeight: 40,
      };
    }
  }, [loadedFont, displayText, fontSize, strokeWidth, instanceId, editable, placeholder]);

  // Input change handler for editable mode
  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const incoming = e.target.value;
      const truncated = truncateToWordsAndLength(incoming, maxWords, maxLength);
      setText(truncated);
      onChange?.(truncated);
    },
    [maxWords, maxLength, onChange]
  );

  const activeColor = isShowingPlaceholder ? "rgba(156, 163, 175, 0.45)" : color;

  // Render fallback if font not loaded yet
  const fontClass = fontCssClassMap[font] || "font-reenie-beanie";

  return (
    <span
      ref={containerRef}
      onClick={() => {
        if (editable && inputRef.current) {
          inputRef.current.focus();
        }
      }}
      className={`relative inline-flex items-center align-middle ${
        editable ? "cursor-text select-none group" : ""
      } ${className}`}
      style={{ minHeight: `${Math.round(fontSize * 1.35)}px` }}
    >
      {/* Hidden input field for capturing keystrokes in editable mode */}
      {editable && (
        <input
          ref={inputRef}
          type="text"
          value={text}
          onChange={handleInputChange}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          className="sr-only"
          aria-label="Handwriting input"
        />
      )}

      {/* Fallback text shown while font is parsing or in SSR */}
      {!loadedFont ? (
        <span
          className={`relative inline-block ${fontClass} transition-opacity ${
            !animate && inView ? "opacity-100" : "opacity-0"
          } ${textClassName}`}
          style={{
            color: activeColor,
            fontSize: `${fontSize}px`,
            lineHeight: `${Math.round(fontSize * 1.35)}px`,
          }}
        >
          {displayText}
        </span>
      ) : (
        <span className="relative inline-flex items-center">
          <svg
            viewBox={viewBox}
            style={{
              width: `${svgWidth}px`,
              height: `${svgHeight}px`,
            }}
            className="block overflow-visible select-none pointer-events-none"
            fill="none"
          >
            <g>
              {pathItems.map((item) => {
                if (item.isSpace || !item.d || item.nonSpaceIndex < 0) {
                  return null;
                }

                // Calculate stagger timing so total writing duration matches animationDuration
                const totalNonSpace = Math.max(1, pathItems.filter((p) => !p.isSpace).length);
                const totalSec = animationDuration / 1000;
                const overlapFactor = 0.65;
                const charDuration = Math.max(
                  0.1,
                  totalSec / (1 + (totalNonSpace - 1) * overlapFactor)
                );
                const step = charDuration * overlapFactor;
                const charDelay =
                  animationDelay / 1000 + item.nonSpaceIndex * step;

                return (
                  <motion.path
                    key={item.id}
                    d={item.d}
                    stroke={activeColor}
                    strokeWidth={strokeWidth}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill={activeColor}
                    fillRule="nonzero"
                    initial={
                      animate
                        ? { pathLength: 0, strokeOpacity: 0, fillOpacity: 0 }
                        : { pathLength: 1, strokeOpacity: 1, fillOpacity: 1 }
                    }
                    animate={
                      inView
                        ? { pathLength: 1, strokeOpacity: 1, fillOpacity: 1 }
                        : { pathLength: 0, strokeOpacity: 0, fillOpacity: 0 }
                    }
                    transition={animate ? {
                      pathLength: {
                        duration: charDuration,
                        delay: charDelay,
                        ease: [0.25, 0.1, 0.25, 1],
                      },
                      strokeOpacity: {
                        duration: 0,
                        delay: charDelay,
                      },
                      fillOpacity: {
                        duration: charDuration * 0.45,
                        delay: charDelay + charDuration * 0.55,
                        ease: "easeOut",
                      },
                    } : INSTANT}
                  />
                );
              })}
            </g>
          </svg>

          {/* Interactive typing indicator / blinking cursor in editable mode */}
          {editable && isFocused && (
            <motion.span
              animate={{ opacity: [1, 0, 1] }}
              transition={{ repeat: Infinity, duration: 0.8, ease: "easeInOut" }}
              className="inline-block ml-1 w-0.5 h-6 rounded-full"
              style={{ backgroundColor: color }}
            />
          )}
        </span>
      )}
    </span>
  );
}

"use client";

import type { Font } from "opentype.js";

export type HandwritingFont = "reenie-beanie" | "caveat" | "kalam";

export const LOCAL_FONT_PATHS: Record<HandwritingFont, string> = {
  "reenie-beanie": "/fonts/ReenieBeanie-Regular.ttf",
  caveat: "/fonts/Caveat-Regular.ttf",
  kalam: "/fonts/Kalam-Regular.ttf",
};

export const CDN_FONT_URLS: Record<HandwritingFont, string> = {
  "reenie-beanie":
    "https://raw.githubusercontent.com/google/fonts/main/ofl/reeniebeanie/ReenieBeanie.ttf",
  caveat:
    "https://raw.githubusercontent.com/google/fonts/main/ofl/caveat/Caveat%5Bwght%5D.ttf",
  kalam:
    "https://raw.githubusercontent.com/google/fonts/main/ofl/kalam/Kalam-Regular.ttf",
};

const fontCache = new Map<string, Font>();
const pendingLoads = new Map<string, Promise<Font>>();

/**
 * Loads and parses an opentype Font from a local path or fallback CDN URL.
 * Uses an in-memory cache to ensure each font is downloaded and parsed only once.
 */
export async function loadHandwritingFont(
  font: HandwritingFont = "reenie-beanie",
  customUrl?: string
): Promise<Font> {
  const primaryUrl = customUrl || LOCAL_FONT_PATHS[font] || LOCAL_FONT_PATHS["reenie-beanie"];
  const fallbackUrl = customUrl ? undefined : CDN_FONT_URLS[font];

  const cacheKey = customUrl || font;
  const cached = fontCache.get(cacheKey);
  if (cached) {
    return cached;
  }

  const existingPending = pendingLoads.get(cacheKey);
  if (existingPending) {
    return existingPending;
  }

  const loadPromise = (async () => {
    const opentypeModule = await import("opentype.js");
    const opentype = opentypeModule.default || opentypeModule;

    const fetchArrayBuffer = async (url: string): Promise<ArrayBuffer> => {
      const res = await fetch(url);
      if (!res.ok) {
        throw new Error(`Failed to fetch font at ${url} (${res.status} ${res.statusText})`);
      }
      return res.arrayBuffer();
    };

    let buffer: ArrayBuffer;
    try {
      buffer = await fetchArrayBuffer(primaryUrl);
    } catch (err) {
      if (fallbackUrl) {
        buffer = await fetchArrayBuffer(fallbackUrl);
      } else {
        throw err;
      }
    }

    const parsedFont = opentype.parse(buffer);
    fontCache.set(cacheKey, parsedFont);
    pendingLoads.delete(cacheKey);
    return parsedFont;
  })();

  pendingLoads.set(cacheKey, loadPromise);
  return loadPromise;
}

"use client";

import { useEffect, useState } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

/**
 * Whether an annotation should animate: the caller's `animate` prop, turned off when the
 * visitor asks for reduced motion. The mark is then drawn in its final state straight away.
 *
 * The media query is read after mount, so server and client render the same markup
 * (no hydration mismatch); the switch happens before any mark starts drawing.
 */
export function useRoughMotion(animate: boolean): boolean {
  const [reduce, setReduce] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return undefined;
    const mq = window.matchMedia(QUERY);
    const update = () => setReduce(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);

  return animate && !reduce;
}

/** Transition used when an annotation must not animate: jump straight to the final state. */
export const INSTANT = { duration: 0 } as const;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
